def test_new_row_registration_refuses_stale_implicit_machine(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
    operation: str,
    arguments: tuple[str, ...],
) -> None:
    monkeypatch.delenv("WRKSLOTS_MACHINE")
    local_machine = wrkslots._short_hostname()
