def test_inode_range_filter_is_bounded_and_covers_every_selected_identity(
    tmp_path: Path,
) -> None:
    selected = {
        (device % 7 + 1, inode): ()
        for device, inode in enumerate(range(1, 100_000, 97))
    }
    ranges = wrkslots._bounded_inode_ranges(selected)

    assert len(ranges) <= wrkslots._PROCESS_CENSUS_INODE_RANGE_LIMIT
    assert all(
        any(first <= inode <= last for first, last in ranges)
        for _device, inode in selected
    )

    probe = tmp_path / "probe"
    probe.write_bytes(b"probe")
    identity = probe.stat()
    first = max(1, identity.st_ino - 512)
    covering = {
        (identity.st_dev, inode): ()
        for inode in range(first, identity.st_ino + 513)
    }
    returncode, stdout, stderr = wrkslots._run_bounded_read_only_command(
        (
            "/usr/bin/find",
            "-L",
            str(probe),
            "-maxdepth",
            "0",
            "(",
            *wrkslots._find_inode_selection(covering),
            ")",
            "-printf",
            "%p\\0",
        ),
        stdout_limit=4096,
    )
    assert returncode == 0
    assert stdout == os.fsencode(probe) + b"\0"
    assert stderr == b""


def test_privileged_inode_filter_discards_unrelated_fds_but_not_evidence(
    tmp_path: Path,
) -> None:
    descriptors = tmp_path / "fd"
    selected = tmp_path / "selected"
    outside = tmp_path / "outside"
    descriptors.mkdir()
    selected.mkdir()
    outside.mkdir()
    selected_file = selected / "held"
    selected_file.write_bytes(b"selected")
    selected_identity = selected_file.stat()
    outside_alias = outside / "alias"
    os.link(selected_file, outside_alias)
    unrelated = outside / "unrelated"
    unrelated.write_bytes(b"unrelated")
    for descriptor in range(4096):
        (descriptors / f"unrelated-{descriptor}").symlink_to(unrelated)
    selected_descriptor = descriptors / "selected"
    selected_descriptor.symlink_to(outside_alias)
    socket_path = outside / "socket"
    holder = socket.socket(socket.AF_UNIX, socket.SOCK_STREAM)
    holder.bind(str(socket_path))
    socket_descriptor = descriptors / "socket"
    socket_descriptor.symlink_to(socket_path)
    inodes = {(selected_identity.st_dev, selected_identity.st_ino): ()}
    command = (
        "/usr/bin/find",
        "-L",
        str(descriptors),
        "-mindepth",
        "1",
        "-maxdepth",
        "1",
        "(",
        *wrkslots._find_inode_selection(inodes),
        ")",
        "-printf",
        "%p\\0%D\\0%i\\0%y\\0",
    )
    try:
        returncode, stdout, stderr = wrkslots._run_bounded_read_only_command(
            command, stdout_limit=1024
        )
        assert returncode == 0
        assert stderr == b""
        rows = wrkslots._census_nul_records(stdout, 4, "test inode find")
        assert {row[0] for row in rows} == {
            str(selected_descriptor),
            str(socket_descriptor),
        }

        # Producer selection is not truncation. Relevant output still refuses
        # instead of authorizing a clear result from a prefix.
        for descriptor in range(64):
            (descriptors / f"selected-{'x' * 40}-{descriptor}").symlink_to(
                outside_alias
            )
        with pytest.raises(wrkslots.Refusal, match="stdout exceeded 1024 bytes"):
            wrkslots._run_bounded_read_only_command(
                command, stdout_limit=1024
            )
    finally:
        holder.close()


def test_privileged_find_compacts_large_target_set_and_keeps_exact_matches(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    parent = Path("/srv/worktrees/slots")
    targets = {
        parent / f"slot-{index:03d}-{'x' * 64}": f"slot-{index:03d}"
        for index in range(293)
    }
    exact_selection = wrkslots._find_link_selection(targets)
    assert sum(len(os.fsencode(arg)) + 1 for arg in exact_selection) > 48 * 1024

    process = wrkslots._AbsentProcessObservation(123, 17, "/other", "mnt:[123]")
    selected = next(reversed(targets))
    unrelated = parent / "not-selected" / "held"
    evidence = b"".join(
        (
            b"/proc/123/fd/8\0",
            os.fsencode(selected / "held") + b"\0",
            b"/proc/123/fd/9\0",
            os.fsencode(unrelated) + b"\0",
        )
    )
    calls: list[tuple[str, ...]] = []
    monkeypatch.setattr(
        wrkslots, "_process_symlink_roots", lambda _processes: ("/proc/123/fd",)
    )
    monkeypatch.setattr(wrkslots, "_process_start_ticks", lambda _path: 17)

    def bounded_find(
        _program: Path,
        arguments: Sequence[str],
        **_kwargs: object,
    ) -> tuple[int, bytes, bytes]:
        calls.append(tuple(arguments))
        assert sum(len(os.fsencode(arg)) + 1 for arg in arguments) < 48 * 1024
        pairs = tuple(zip(arguments, arguments[1:]))
        assert ("-lname", str(parent / "*")) in pairs
        return 0, evidence, b""

    monkeypatch.setattr(wrkslots, "_run_root_owned_command", bounded_find)

    assert wrkslots._absent_validate_find_matches((process,), targets) == (
        (123, targets[selected], "link", str(selected / "held")),
    )
    assert len(calls) == 1


def test_compacted_find_selection_is_a_producer_superset(tmp_path: Path) -> None:
    link_root = tmp_path / "links"
    link_root.mkdir()
    parent = Path("/srv/worktrees/slots")
    targets = {
        parent / f"slot-{index:03d}-{'x' * 64}": f"slot-{index:03d}"
        for index in range(293)
    }
    selected = next(reversed(targets))
    selected_link = link_root / "selected"
    unrelated_link = link_root / "unrelated"
    selected_link.symlink_to(selected / "held")
    unrelated_link.symlink_to(parent / "not-selected" / "held")
    selection = wrkslots._bounded_find_link_selection(targets)

    returncode, stdout, stderr = wrkslots._run_bounded_read_only_command(
        (
            "/usr/bin/find",
            "-P",
            str(link_root),
            "-maxdepth",
            "1",
            "-type",
            "l",
            "(",
            *selection,
            ")",
            "-printf",
            "%p\\0%l\\0",
        )
    )

    assert returncode == 0
    assert stderr == b""
    assert {
        tuple(record)
        for record in wrkslots._census_nul_records(stdout, 2, "compacted find")
    } == {
        (str(selected_link), str(selected / "held")),
        (str(unrelated_link), str(parent / "not-selected" / "held")),
    }


def test_privileged_find_discards_all_batches_after_process_generation_changes(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    process = wrkslots._AbsentProcessObservation(123, 17, "/other", "mnt:[123]")
    target = Path("/srv/worktrees/slots/selected")
    roots = tuple(
        f"/proc/123/fd/{index}-{'x' * 1024}" for index in range(100)
    )
    generation = 17
    calls = 0
    monkeypatch.setattr(wrkslots, "_process_symlink_roots", lambda _processes: roots)
    monkeypatch.setattr(wrkslots, "_process_start_ticks", lambda _path: generation)

    def mutating_find(
        _program: Path,
        _arguments: Sequence[str],
        **_kwargs: object,
    ) -> tuple[int, bytes, bytes]:
        nonlocal calls, generation
        calls += 1
        if calls == 1:
            return 0, b"/proc/123/fd/8\0/srv/worktrees/slots/selected/held\0", b""
        generation = 18
        return 0, b"", b""

    monkeypatch.setattr(wrkslots, "_run_root_owned_command", mutating_find)

    # A matched holder that changed identity is a hard refusal, not a retry:
    # a child forked outside the snapshot can still hold the selected path.
    with pytest.raises(
        wrkslots.Refusal,
        match=(
            r"^PID 123 identity changed after privileged find matched a selected "
            r"path; the selected path may still be in use$"
        ),
    ) as refused:
        wrkslots._absent_validate_find_matches((process,), {target: "selected"})
    assert type(refused.value) is wrkslots.Refusal
    assert calls > 1



def test_batch_unix_census_preserves_uncertainty_and_generation_guards(
    tmp_path: Path, monkeypatch: pytest.MonkeyPatch,
) -> None:
    process = wrkslots._AbsentProcessObservation(4242, 17, "", "mnt:[1]")
    header = b"Num RefCount Protocol Flags Type St Inode Path\n"
    monkeypatch.setattr(wrkslots, "_batch_network_namespaces", lambda *_args: {4242: "net:[1]"})
    monkeypatch.setattr(wrkslots, "_process_generation_is_current", lambda _p: True)
    monkeypatch.setattr(wrkslots, "_run_same_uid_command", lambda *_a, **_k: (127, b"", b"unavailable"))
    for contents, reason, holders in (
        (b"bad\n", "malformed header", {}),
        (header + b"bad\n", "malformed record", {}),
        (header + b"0: 2 0 0 1 1 123 relative-socket\n", "relative bound pathname", {123: {4242}}),
        (header + b"0: 2 0 0 1 1 123  \n", "relative bound pathname", {123: {4242}}),
        (header, "held socket identities are absent", {123: {4242}}),
        (header + f"0: 2 0 0 1 1 123 {tmp_path}/socket\n".encode(), "without a stable observed holder", {}),
    ):
        monkeypatch.setattr(wrkslots, "_run_root_owned_command", lambda *_a, data=contents, **_k: (0, data, b""))
        with pytest.raises(wrkslots.Refusal, match=reason):
            wrkslots._batch_unix_socket_matches((process,), {tmp_path: str(tmp_path)}, holders, wrkslots._ReadOnlyCommandBudget.start(timeout_seconds=22, stdout_limit=4096, stderr_limit=4096), selected_has_sockets=True)
    monkeypatch.setattr(wrkslots, "_run_root_owned_command", lambda *_a, **_k: (0, header, b""))
    monkeypatch.setattr(wrkslots, "_process_generation_is_current", lambda _p: False)
    with pytest.raises(wrkslots._ProcessEvidenceChanged, match="representatives changed"):
        wrkslots._batch_unix_socket_matches((process,), {tmp_path: str(tmp_path)}, {}, wrkslots._ReadOnlyCommandBudget.start(timeout_seconds=22, stdout_limit=4096, stderr_limit=4096))


def test_batch_unix_census_filters_current_scale_at_privileged_producer(
    tmp_path: Path, monkeypatch: pytest.MonkeyPatch,
) -> None:
    process = wrkslots._AbsentProcessObservation(4242, 17, "", "mnt:[1]")
    header = b"Num RefCount Protocol Flags Type St Inode Path\n"
    row = b"0: 2 0 0 1 1 123\n"
    contents = header + row * ((5 * 1024 * 1024) // len(row) + 1)
    assert 4 * 1024 * 1024 < len(contents) < wrkslots._UNIX_SOCKET_TABLE_BYTES_LIMIT
    table = tmp_path / "unix"
    table.write_bytes(contents)
    monkeypatch.setattr(
        wrkslots, "_batch_network_namespaces", lambda *_args: {4242: "net:[1]"}
    )
    monkeypatch.setattr(wrkslots, "_process_generation_is_current", lambda _p: True)
    calls: list[tuple[Path, tuple[str, ...], bytes, int]] = []

    def filtered_root(
        program: Path,
        arguments: Sequence[str],
        *,
        input_data: bytes | None = None,
        input_limit: int = 1024 * 1024,
        budget: wrkslots._ReadOnlyCommandBudget | None = None,
    ) -> tuple[int, bytes, bytes]:
        assert input_data is not None
        calls.append((program, tuple(arguments), input_data, input_limit))
        return wrkslots._run_bounded_read_only_command(
            (str(program), *arguments[:-1], str(table)),
            input_data=input_data,
            input_limit=input_limit,
            stdout_limit=wrkslots._PROCESS_CENSUS_OUTPUT_BYTES_LIMIT,
        )

    monkeypatch.setattr(wrkslots, "_run_root_owned_command", filtered_root)
    budget = wrkslots._ReadOnlyCommandBudget.start(
        timeout_seconds=22,
        stdout_limit=wrkslots._PROCESS_CENSUS_OUTPUT_BYTES_LIMIT,
        stderr_limit=4096,
    )
    assert wrkslots._batch_unix_socket_matches(
        (process,), {tmp_path: str(tmp_path)}, {}, budget
    ) == ()
    assert calls == [
        (
            Path("/usr/bin/gawk"),
            ("--", wrkslots._BATCH_UNIX_AWK, "/proc/4242/net/unix"),
            f"{tmp_path}\n".encode(),
            wrkslots._PROCESS_CENSUS_SELECTION_BYTES_LIMIT,
        )
    ]

    oversized = b"x" * (wrkslots._UNIX_SOCKET_TABLE_BYTES_LIMIT + 1)
    monkeypatch.setattr(
        wrkslots,
        "_run_root_owned_command",
        lambda *_args, **_kwargs: (0, oversized, b""),
    )
    with pytest.raises(wrkslots.Refusal, match="Unix socket census is incomplete"):
        wrkslots._batch_unix_socket_matches(
            (process,), {tmp_path: str(tmp_path)}, {}, budget
        )


def test_unix_socket_producer_preserves_relevant_rows_and_refuses_truncation(
    tmp_path: Path,
) -> None:
    selected = tmp_path / "selected"
    selected.mkdir()
    header = "Num RefCount Protocol Flags Type St Inode Path\n"
    unrelated = "0: 2 0 0 1 1 123 /outside/socket\n"
    relevant = f"0: 2 0 0 1 1 456 {selected}/socket\n"
    table = tmp_path / "unix"
    table.write_text(header + unrelated * 4096 + relevant, encoding="utf-8")
    command = ("/usr/bin/gawk", "--", wrkslots._BATCH_UNIX_AWK, str(table))
    selection = f"{selected}\n".encode()

    returncode, stdout, stderr = wrkslots._run_bounded_read_only_command(
        command,
        input_data=selection,
        input_limit=len(selection),
        stdout_limit=4096,
    )

    assert returncode == 0
    assert stdout == (header + relevant).encode()
    assert stderr == b""

    table.write_text(header + relevant.rstrip("\n"), encoding="utf-8")
    returncode, _stdout, stderr = wrkslots._run_bounded_read_only_command(
        command,
        input_data=selection,
        input_limit=len(selection),
        stdout_limit=4096,
    )
    assert returncode == 2
    assert b"missing final newline" in stderr


@pytest.mark.ordinary_environment
def test_batch_maps_filter_preserves_large_inode_strings_and_read_errors(tmp_path: Path) -> None:
    path = tmp_path / "maps"
    first = "1-2 r--p 0 00:30 9007199254740992 /outside/one"
    second = "2-3 r--p 0 00:30 9007199254740993 /outside/two"
    path.write_text(first + "\n" + second + "\n")
    def budget() -> wrkslots._ReadOnlyCommandBudget:
        return wrkslots._ReadOnlyCommandBudget.start(timeout_seconds=22, stdout_limit=4096, stderr_limit=4096)
    for inode, expected in (("9007199254740992", first), ("9007199254740993", second)):
        rc, out, err = wrkslots._run_root_owned_command(
            Path("/usr/bin/gawk"), ("--", wrkslots._BATCH_MAPS_AWK, str(path)),
            input_data=f"i{inode}\n".encode(), budget=budget(),
        )
        assert rc == 0 and not err, (out, err)
        assert out == f"{path}:{expected}\n".encode()
    rc, out, err = wrkslots._run_root_owned_command(
        Path("/usr/bin/gawk"), ("--", wrkslots._BATCH_MAPS_AWK, str(path / "missing")),
        input_data=b"i9007199254740992\n", budget=budget(),
    )
    assert rc == 1 and not out and str(path / "missing").encode() in err


def test_batch_maps_filter_uses_its_bounded_selection_input_ceiling(
    tmp_path: Path, monkeypatch: pytest.MonkeyPatch,
) -> None:
    process = wrkslots._AbsentProcessObservation(4242, 17, "", "mnt:[1]")
    observed: dict[str, object] = {}

    def root_command(
        program: Path,
        arguments: Sequence[str],
        **kwargs: object,
    ) -> tuple[int, bytes, bytes]:
        observed.update(program=program, arguments=arguments, **kwargs)
        return 0, b"", b""

    monkeypatch.setattr(wrkslots, "_run_root_owned_command", root_command)
    budget = wrkslots._ReadOnlyCommandBudget.start(
        timeout_seconds=22,
        stdout_limit=4096,
        stderr_limit=4096,
        input_limit=wrkslots._MOUNTINFO_CENSUS_BYTES_LIMIT,
    )
    assert (
        wrkslots._batch_maps_inode_matches(
            (process,),
            {tmp_path: str(tmp_path)},
            {(48, 19): ((str(tmp_path), "selected file"),)},
            budget,
        )
        == ()
    )
    assert observed["program"] == Path("/usr/bin/gawk")
    assert observed["input_limit"] == wrkslots._PROCESS_CENSUS_SELECTION_BYTES_LIMIT
    assert observed["budget"] is budget


def test_batch_network_namespace_links_require_complete_generation_bound_records(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    process = wrkslots._AbsentProcessObservation(4242, 17, "", "mnt:[1]")
    monkeypatch.setattr(wrkslots, "_process_generation_is_current", lambda _p: True)
    for rc, out, err, reason in (
        (0, b"", b"", "omitted PID"),
        (0, b"/proc/4242/ns/net\0\0", b"", "unreadable or malformed"),
        (0, b"/proc/9999/ns/net\0net:[1]\0", b"", "unexpected path"),
        (1, b"", b"/usr/bin/find: '/proc/4242/ns/net': Permission denied\n", "produced diagnostics"),
    ):
        monkeypatch.setattr(wrkslots, "_run_root_owned_command", lambda *_a, value=(rc, out, err), **_k: value)
        with pytest.raises(wrkslots.Refusal, match=reason):
            wrkslots._batch_network_namespaces((process,), wrkslots._ReadOnlyCommandBudget.start(timeout_seconds=22, stdout_limit=4096, stderr_limit=4096))


@pytest.mark.ordinary_environment
@pytest.mark.parametrize("kind", ["relative-with-other-fd", "absolute-hardlink", "deleted-original", "rebound-original"])
def test_batch_census_two_selected_trees_cannot_mask_socket_holder(
    tmp_path: Path, lsof_tmpfs_fixture: Path, monkeypatch: pytest.MonkeyPatch, kind: str,
) -> None:
    first, second, unrelated = (lsof_tmpfs_fixture / name for name in ("first", "second", "unrelated"))
    for path in (first, second, unrelated):
        path.mkdir()
    (first / "open-file").write_bytes(b"a separate selected-tree descriptor")
    code = textwrap.dedent(r'''
        import os, socket, sys
        from pathlib import Path
        first, second, kind = Path(sys.argv[1]), Path(sys.argv[2]), sys.argv[3]
        sock = socket.socket(socket.AF_UNIX, socket.SOCK_STREAM)
        if kind == "relative-with-other-fd":
            held_file = open(first / "open-file", "rb")
            os.chdir(second)
            sock.bind("@socket")
        else:
            sock.bind(str(first / "socket"))
            os.link(first / "socket", second / "hardlink")
            if kind in ("deleted-original", "rebound-original"):
                (first / "socket").unlink()
            if kind == "rebound-original":
                replacement = socket.socket(socket.AF_UNIX, socket.SOCK_STREAM)
                replacement.bind(str(first / "socket"))
        os.chdir("/")
        print("ready", flush=True)
        assert sys.stdin.read(1) == "q"
    ''')
    process = subprocess.Popen(
        [sys.executable, "-B", "-c", code, str(first), str(second), kind],
        stdin=subprocess.PIPE, stdout=subprocess.PIPE, stderr=subprocess.PIPE,
        text=True, cwd="/",
    )
    try:
        assert process.stdout is not None
        assert select.select([process.stdout], [], [], 5)[0], "holder did not become ready"
        assert process.stdout.readline() == "ready\n"
        proc = Path(f"/proc/{process.pid}")
        generation = wrkslots._process_start_ticks(proc)
        namespace = wrkslots._mount_namespace(proc)
        assert generation is not None and namespace is not None
        assert os.readlink(proc / "cwd") == "/"
        bound = second / ("@socket" if kind == "relative-with-other-fd" else "hardlink")
        assert bound.is_socket()
        if kind == "absolute-hardlink":
            a, b = (first / "socket").stat(), bound.stat()
            assert (a.st_dev, a.st_ino) == (b.st_dev, b.st_ino)
        elif kind == "deleted-original":
            assert not (first / "socket").exists()
        elif kind == "rebound-original":
            assert (first / "socket").is_socket()
            a, b = (first / "socket").stat(), bound.stat()
            assert (a.st_dev, a.st_ino) != (b.st_dev, b.st_ino)
        observation = wrkslots._AbsentProcessObservation(process.pid, generation, "", namespace)
        monkeypatch.setattr(wrkslots, "_absent_validate_process_snapshot", lambda **_kw: (observation,))
        (tmp_path / "unix.raw").write_bytes((proc / "net/unix").read_bytes())
        budget = wrkslots._ReadOnlyCommandBudget.start(
            timeout_seconds=22, stdout_limit=16 * 1024 * 1024, stderr_limit=64 * 1024,
            input_limit=wrkslots._MOUNTINFO_CENSUS_BYTES_LIMIT,
        )
        with pytest.raises(wrkslots.Refusal, match="filesystem socket node; socket-object liveness is unproven") as refused:
            census = wrkslots._capture_lsof_process_path_census((first, second), budget=budget)
            # A's known match cannot make B's actual held socket safe to remove.
            census.assert_slot_unused(second, None)
        (tmp_path / "REFUSAL.txt").write_text(str(refused.value) + "\n")
        clear = wrkslots._capture_lsof_process_path_census((unrelated,), budget=budget)
        clear.assert_slot_unused(unrelated, None)
        stdout_text, stderr_text = process.communicate("q", timeout=5)
        assert process.returncode == 0, (stdout_text, stderr_text)
    finally:
        terminate_process(process)


def test_ownerless_validate_batch_retains_shared_census_use_and_other(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
    capsys: pytest.CaptureFixture[str],
) -> None:
    project, repository, _remote = make_project(tmp_path)
    held, held_record = prepare_legacy_validate_checkout(
        project, repository, name="held"
    )
    unused, unused_record = prepare_legacy_validate_checkout(
        project, repository, name="unused"
    )
    held.chmod(0o700)
    unused.chmod(0o700)
    monkeypatch.setattr(
        wrkslots,
        "_capture_lsof_process_path_census",
        lambda _paths, **_kwargs: wrkslots._ProcessPathCensus(
            (), ((os.getpid(), str(held), "fd", str(held)),), owner_cgroup_complete=False
        ),
    )
    monkeypatch.setattr(
        wrkslots,
        "_capture_same_uid_process_path_census",
        lambda _paths, **_kwargs: wrkslots._ProcessPathCensus(
            (), (), owner_cgroup_complete=False
        ),
    )

    rc = wrkslots.main(
        [
            "--project-root",
            str(project),
            "recover-ownerless-validate-batch",
            "--coordinator-authorized",
            "--coordinator-pid",
            str(os.getpid()),
            "--checkout",
            held.relative_to(project).as_posix(),
            "--checkout",
            unused.relative_to(project).as_posix(),
            "--completed-record",
            held_record.relative_to(project).as_posix(),
            "--completed-record",
            unused_record.relative_to(project).as_posix(),
            "--repository",
            repository.relative_to(project).as_posix(),
            "--repository",
            repository.relative_to(project).as_posix(),
            "--format",
            "json",
        ]
    )

    assert rc == 0
    report = json.loads(capsys.readouterr().out)
    assert report["removed"] == []
    assert len(report["retained"]) == 2
    retained = {item["checkout"]: item["reason"] for item in report["retained"]}
    assert f"live process {os.getpid()}" in retained[held.relative_to(project).as_posix()]
    assert (
        "ownerless linked validation checkout recovery is disabled"
        in retained[unused.relative_to(project).as_posix()]
    )
    assert held.is_dir()
    assert unused.is_dir()


