@pytest.mark.ordinary_environment
def test_process_entering_after_final_scan_before_path_move_is_not_deleted(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
    capsys: pytest.CaptureFixture[str],
) -> None:
    project, repository, _remote = make_project(tmp_path)
    made = create(project)
    assert made.returncode == 0, made.stderr
    commit_task(repository, checkout(project), "codex/task")
    handed_off = finish(project)
    assert handed_off.returncode == 0, handed_off.stderr
    mark_owner_dead(project)
    set_liveness(project, "dead")
    original_assert = wrkslots._assert_slot_unused
    calls = 0
    entrant: subprocess.Popen[str] | None = None
    focused_proc = tmp_path / "focused-proc"
    focused_proc.mkdir()

    def enter_after_scan(
        slot_path: Path,
        record: wrkslots.ActiveRecord | None = None,
        *,
        use_lsof: bool = True,
        ignore_invoking_ancestry: bool = False,
        census: wrkslots._ProcessPathCensus | None = None,
        fallback_census: wrkslots._ProcessPathCensus | None = None,
        proc_root: Path = Path("/proc"),
        ignore_current_process: bool = True,
        live_use_recheck: wrkslots._LiveUseRecheckBudget | None = None,
    ) -> None:
        nonlocal calls, entrant
        original_assert(
            slot_path,
            record,
            # This test owns the one process whose late entry matters. Keep its
            # real kernel evidence, but do not make the race assertion enumerate
            # every unrelated process on a shared development host. Dedicated
            # census tests exercise the all-process and lsof implementations.
            use_lsof=False,
            ignore_invoking_ancestry=ignore_invoking_ancestry,
            census=census,
            fallback_census=fallback_census,
            proc_root=focused_proc,
            ignore_current_process=ignore_current_process,
            live_use_recheck=live_use_recheck,
        )
        calls += 1
        if calls == 2:
            entrant = subprocess.Popen(
                [
                    sys.executable,
                    "-c",
                    "import os,sys,time; os.chdir(sys.argv[1]); "
                    "print(os.getcwd(), flush=True); time.sleep(60)",
                    str(checkout(project)),
                ],
                text=True,
                stdout=subprocess.PIPE,
                stderr=subprocess.PIPE,
            )
            assert entrant.stdout is not None
            assert entrant.stdout.readline().strip() == str(checkout(project))
            (focused_proc / str(entrant.pid)).symlink_to(
                Path("/proc") / str(entrant.pid), target_is_directory=True
            )

    monkeypatch.setattr(wrkslots, "_assert_slot_unused", enter_after_scan)
    try:
        returncode = wrkslots.main(
            [
                "--project-root",
                str(project),
                "remove",
                "slot01",
                "--coordinator-authorized",
                "--coordinator-pid",
                str(os.getpid()),
                "--expected-generation",
                "1",
                # The focused /proc root above applies to the checks made
                # under the lock.  Default remove of an agent slot is a batch
                # of one, whose checks always read all of /proc; its late
                # entrants are covered by the remove-agent-batch tests
                # test_remove_agent_batch_fresh_scan_catches_a_process_that_starts_after_the_census
                # and test_remove_agent_batch_checks_the_fenced_path_by_identity_before_deleting.
                "--no-lock-budget",
            ]
        )

        assert returncode == 3
        assert "live process" in capsys.readouterr().err
        assert entrant is not None
        assert checkout(project).is_dir()
        assert Path(os.readlink(f"/proc/{entrant.pid}/cwd")) == checkout(project)
        assert not list((project / "worktrees").glob(".slot01.fenced.*"))
        assert not (project / "worktrees" / "ACTIVE.testhost.journal").exists()
        assert len(active_slots(project)) == 1
    finally:
        if entrant is not None:
            terminate_process(entrant)


