@pytest.mark.parametrize("authority", ("digest", "exact"))
@pytest.mark.parametrize("redirect", ("pushurl", "pushInsteadOf"))
def test_remote_authority_accepts_no_pushurl_and_refuses_override(
    tmp_path: Path,
    authority: str,
    redirect: str,
) -> None:
    _project, repository, _remote = make_project(tmp_path)
    vcs = wrkslots._GitVcs()
    authorized_url = git(repository, "remote", "get-url", "origin").stdout.strip()
    expected_digest = hashlib.sha256(authorized_url.encode("utf-8")).hexdigest()
    assert (
        git(
            repository,
            "config",
            "--get-all",
            "remote.origin.pushurl",
            check=False,
        ).returncode
        == 1
    )

    if authority == "digest":
        assert vcs.remote_url_sha256(repository, "origin") == expected_digest
    else:
        assert vcs.assert_remote_url(repository, "origin", authorized_url) == expected_digest

    redirected = str(tmp_path / "redirect.git")
    if redirect == "pushurl":
        git(repository, "config", "remote.origin.pushurl", redirected)
        expected = "remote 'origin' has a configured push URL"
    else:
        git(repository, "config", f"url.{redirected}.pushInsteadOf", authorized_url)
        expected = "effective push URL differs from its single fetch URL"
    assert (
        git(repository, "remote", "get-url", "--push", "--all", "origin").stdout.strip()
        == redirected
    )
    with pytest.raises(wrkslots.Refusal, match=expected):
        if authority == "digest":
            vcs.remote_url_sha256(repository, "origin")
        else:
            vcs.assert_remote_url(repository, "origin", authorized_url)


def test_salvage_push_ignores_pushurl_installed_at_network_boundary(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    _project, repository, authorized_remote = make_project(tmp_path)
    evil_remote = tmp_path / "evil.git"
    subprocess.run(
        ["git", "init", "--bare", "--initial-branch=main", str(evil_remote)],
        check=True,
        capture_output=True,
        text=True,
    )
    commit = commit_local(repository, "local-only.txt", "preserve me\n", "local")
    rescue_ref = "refs/salvage/test-boundary"
    original_run = wrkslots._GitVcs._run
    network_calls: list[tuple[str, ...]] = []
    mutated = False

    def mutate_before_push(
        repository_path: Path,
        args: Sequence[str],
        *,
        check: bool = True,
        input_text: str | None = None,
        env_overrides: Mapping[str, str] | None = None,
    ) -> subprocess.CompletedProcess[str]:
        nonlocal mutated
        if args and args[0] in {"ls-remote", "fetch", "push"}:
            network_calls.append(tuple(args))
        if args and args[0] == "push" and not mutated:
            git(repository, "config", "remote.origin.pushurl", str(evil_remote))
            mutated = True
        return original_run(
            repository_path,
            args,
            check=check,
            input_text=input_text,
            env_overrides=env_overrides,
        )

    monkeypatch.setattr(wrkslots._GitVcs, "_run", staticmethod(mutate_before_push))
    vcs = wrkslots._GitVcs()
    authority = vcs.remote_authority(repository, "origin")
    vcs.push_salvage(repository, "origin", commit, rescue_ref, authority)

    assert mutated is True
    push = next(args for args in network_calls if args[0] == "push")
    assert str(authorized_remote) in push
    assert "origin" not in push
    assert git(authorized_remote, "rev-parse", rescue_ref).stdout.strip() == commit
    assert (
        git(evil_remote, "show-ref", "--verify", "--quiet", rescue_ref, check=False)
        .returncode
        == 1
    )
    assert [args[0] for args in network_calls] == [
        "ls-remote",
        "push",
        "ls-remote",
    ]
    assert all(str(authorized_remote) in args for args in network_calls)
    assert all("origin" not in args for args in network_calls)
    assert all(args[0] != "fetch" for args in network_calls)


def test_salvage_push_refuses_redirect_in_isolated_config_at_network_boundary(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    _project, repository, authorized_remote = make_project(tmp_path)
    evil_remote = tmp_path / "evil.git"
    subprocess.run(
        ["git", "init", "--bare", "--initial-branch=main", str(evil_remote)],
        check=True,
        capture_output=True,
        text=True,
    )
    commit = commit_local(repository, "local-only.txt", "preserve me\n", "local")
    rescue_ref = "refs/salvage/test-isolated-config-boundary"
    vcs = wrkslots._GitVcs()
    authority = vcs.remote_authority(repository, "origin")
    original_run = wrkslots._GitVcs._run
    injected = False

    def inject_isolated_redirect(
        repository_path: Path,
        args: Sequence[str],
        *,
        check: bool = True,
        input_text: str | None = None,
        env_overrides: Mapping[str, str] | None = None,
    ) -> subprocess.CompletedProcess[str]:
        nonlocal injected
        if args and args[0] == "push" and not injected:
            git(
                repository_path,
                "config",
                f"url.{evil_remote}.pushInsteadOf",
                authority.url,
            )
            injected = True
        return original_run(
            repository_path,
            args,
            check=check,
            input_text=input_text,
            env_overrides=env_overrides,
        )

    monkeypatch.setattr(
        wrkslots._GitVcs, "_run", staticmethod(inject_isolated_redirect)
    )
    with pytest.raises(wrkslots.Refusal, match="isolated network Git config changed"):
        vcs.push_salvage(repository, "origin", commit, rescue_ref, authority)

    assert injected is True
    for remote in (authorized_remote, evil_remote):
        assert (
            git(remote, "show-ref", "--verify", "--quiet", rescue_ref, check=False)
            .returncode
            == 1
        )


@pytest.mark.parametrize("operation", ("fetch", "read"))
def test_salvage_reads_refuse_redirect_in_isolated_config(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
    operation: str,
) -> None:
    _project, repository, authorized_remote = make_project(tmp_path)
    evil_remote = tmp_path / "evil.git"
    subprocess.run(
        ["git", "init", "--bare", "--initial-branch=main", str(evil_remote)],
        check=True,
        capture_output=True,
        text=True,
    )
    vcs = wrkslots._GitVcs()
    authority = vcs.remote_authority(repository, "origin")
    original_run = wrkslots._GitVcs._run
    injected = False

    def inject_isolated_redirect(
        repository_path: Path,
        args: Sequence[str],
        *,
        check: bool = True,
        input_text: str | None = None,
        env_overrides: Mapping[str, str] | None = None,
    ) -> subprocess.CompletedProcess[str]:
        nonlocal injected
        if args and args[0] == "ls-remote" and not injected:
            git(
                repository_path,
                "config",
                f"url.{evil_remote}.insteadOf",
                authority.url,
            )
            injected = True
        return original_run(
            repository_path,
            args,
            check=check,
            input_text=input_text,
            env_overrides=env_overrides,
        )

    monkeypatch.setattr(
        wrkslots._GitVcs, "_run", staticmethod(inject_isolated_redirect)
    )
    with pytest.raises(wrkslots.Refusal, match="isolated network Git config changed"):
        if operation == "fetch":
            git(repository, "update-ref", "-d", "refs/remotes/origin/main")
            vcs.fetch_remote(
                repository,
                "origin",
                "refs/remotes/origin/main",
                authority,
            )
        else:
            vcs.remote_ref_sha(
                repository,
                "origin",
                "refs/salvage/not-present",
                authority,
            )

    assert injected is True
    assert (
        git(
            evil_remote,
            "for-each-ref",
            "--format=%(refname)",
        ).stdout
        == ""
    )


