def test_agent_reclaim_uses_verified_local_archive_only_after_remote_refuses(
    tmp_path: Path,
) -> None:
    project, tree, _remote, archive_root = prepare_refused_salvage(tmp_path)
    source_head = git(tree, "rev-parse", "HEAD").stdout.strip()
