def _queue_two_finished_slots_with_dead_owners(
    tmp_path: Path, monkeypatch: pytest.MonkeyPatch, *, count: int = 2
) -> tuple[Path, Path, Path]:
    project, repository, remote = make_project(tmp_path)
    for slot, agent, branch in (
        ("slot01", "codex-1", "codex/one"),
        ("slot02", "codex-2", "codex/two"),
        ("slot03", "codex-3", "codex/three"),
    )[:count]:
        assert create(project, slot=slot, agent=agent, branch=branch).returncode == 0
        commit_task(repository, checkout(project, slot=slot), branch)
        source = tmp_path / f"{slot}.md"
        source.write_text(f"retire {slot}\n", encoding="utf-8")
        assert raw_command(
            project,
            "write-handoff",
            slot,
            "--agent",
            agent,
            "--owner-pid",
            str(os.getpid()),
            "--expected-generation",
            "1",
            "--from-file",
            str(source),
        ).returncode == 0
        assert finish(project, slot=slot, agent=agent).returncode == 0
        assert raw_command(
            project,
            "read-handoff",
            slot,
            "--coordinator-pid",
            str(os.getpid()),
        ).returncode == 0
        mark_owner_dead(project, slot=slot)
    set_liveness(project, "dead")
    monkeypatch.setattr(wrkslots, "_assert_slot_unused", lambda *_args, **_kwargs: None)
    return project, repository, remote


def _retire_two(project: Path) -> int:
    return wrkslots.main(
        [
            "--project-root",
            str(project),
            "retire-pending",
            "--limit",
            "2",
            "--coordinator-pid",
            str(os.getpid()),
            "--format",
            "json",
        ]
    )


@pytest.mark.parametrize(
    "drift",
    ("own-repository-registration", "other-repository-registration", "missing-directory"),
)
def test_retire_pending_continues_past_one_targets_own_storage_drift(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
    capsys: pytest.CaptureFixture[str],
    drift: str,
) -> None:
    """A slot whose own storage disagrees with its row does not stop the batch.

    Two of these drifts were seen on a shared host: a worktree of another
    row's repository registered inside the slot, and a row whose slot
    directory is gone.  The removal refuses each before it changes the slot,
    so the target is reported as needing recovery, left exactly as it was,
    and the next candidate is still attempted.
    """

    project, repository, remote = _queue_two_finished_slots_with_dead_owners(
        tmp_path, monkeypatch
    )
    first_slot = checkout(project, slot="slot01").parent
    nested = checkout(project, slot="slot01") / "ignored" / "nested"
    registrar = repository
    if drift == "other-repository-registration":
        registrar = project / "repo-other"
        git(project, "clone", str(remote), str(registrar))
        assert create(
            project,
            slot="other",
            agent="other",
            branch="other/task",
            repository_name="repo-other",
        ).returncode == 0
    if drift == "missing-directory":
        shutil.rmtree(first_slot)
        expected = ["no slot directory"]
    else:
        git(registrar, "worktree", "add", "-b", "nested", str(nested))
        expected = ["registers", str(nested)]
        if drift == "other-repository-registration":
            expected.append("unexpected path")

    code = _retire_two(project)

    assert code == 3
    payload = json.loads(capsys.readouterr().out)
    assert [row["slot"] for row in payload["removed"]] == ["slot02"]
    assert payload["retained"] == []
    assert payload["deferred"] == []
    assert payload["recovery_required"] is True
    [row] = payload["could_not_determine"]
    assert row["slot"] == "slot01"
    assert row["recovery_required"] is True
    for text in expected:
        assert text in row["reason"]
    assert "the slot is unchanged, so the batch continued" in row["reason"]
    config = wrkslots._load_config(str(project), "testhost")
    state = wrkslots._load_active(config, require_repository=False)
    remaining = {(item.slot, item.generation) for item in state.slots}
    assert ("slot01", 1) in remaining
    assert all(slot != "slot02" for slot, _generation in remaining)
    if drift != "missing-directory":
        assert nested.is_dir()
        assert str(nested) in git(registrar, "worktree", "list").stdout


def test_retire_pending_stops_when_a_storage_drift_left_registry_state(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
    capsys: pytest.CaptureFixture[str],
) -> None:
    """The batch goes on after a storage drift only if the registry is untouched."""

    project, _repository, _remote = _queue_two_finished_slots_with_dead_owners(
        tmp_path, monkeypatch
    )
    config = wrkslots._load_config(str(project), "testhost")
    partial = config.control / "ACTIVE.testhost.json.tmp.injected"
    original_remove = wrkslots._cmd_remove

    def drift_then_partial(
        args: argparse.Namespace,
        *,
        private_cleanup: wrkslots._PrivateCleanupContext | None = None,
        validation_removal_proof: wrkslots._ValidationRemovalProof | None = None,
        emit: bool = True,
    ) -> int:
        if args.slot == "slot01":
            record = wrkslots._find_record(
                wrkslots._load_active(config, require_repository=False), "slot01"
            )
            partial.write_text("partial\n", encoding="utf-8")
            raise wrkslots._TargetStorageDrift(
                "injected target storage drift", record=record
            )
        return original_remove(
            args,
            private_cleanup=private_cleanup,
            validation_removal_proof=validation_removal_proof,
            emit=emit,
        )

    monkeypatch.setattr(wrkslots, "_cmd_remove", drift_then_partial)
    code = _retire_two(project)

    assert code == 3
    payload = json.loads(capsys.readouterr().out)
    assert payload["removed"] == []
    [row] = payload["could_not_determine"]
    assert row["slot"] == "slot01"
    assert row["reason"].startswith("injected target storage drift; ")
    assert str(partial) in row["reason"]
    assert [item["slot"] for item in payload["deferred"]] == ["slot02"]
    assert payload["deferred"][0]["reason"] == (
        "batch stopped after an indeterminate retirement outcome"
    )


@pytest.mark.parametrize(
    "failure",
    (
        "remove-OSError",
        "remove-ValueError",
        "remove-RecursionError",
        "remove-RuntimeError",
        "remove-symlink-loop",
        "remove-StopIteration",
        "remove-MemoryError",
        "classification-Refusal",
        "classification-OSError",
        "classification-StopIteration",
    ),
)
def test_retire_pending_reports_its_batch_when_a_later_attempt_fails(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
    capsys: pytest.CaptureFixture[str],
    failure: str,
) -> None:
    """A failure after the first candidate still prints the batch report.

    The first candidate is removed.  The second candidate's removal raises
    a read failure, or it refuses and classifying that refusal fails.  The
    report keeps the first removal and stops at the second, which needs
    recovery.  ``symlink-loop`` makes the second slot's ``HANDOFF.md`` a
    link to itself only after the first removal, so the removal's own
    resolution of that path fails, as it does before Python 3.13.
    """

    stage, kind = failure.split("-", 1)
    if kind == "symlink-loop":
        probe = tmp_path / "loop-probe"
        probe.symlink_to(probe)
        try:
            probe.resolve(strict=False)
        except RuntimeError:
            pass
        else:
            pytest.skip("this Python resolves a symlink loop without raising")
        probe.unlink()
    project, _repository, _remote = _queue_two_finished_slots_with_dead_owners(
        tmp_path, monkeypatch
    )
    config = wrkslots._load_config(str(project), "testhost")
    errors: dict[str, BaseException] = {
        "OSError": OSError(5, "injected read failure"),
        "ValueError": ValueError("injected decode failure"),
        "RecursionError": RecursionError("injected nesting failure"),
        "RuntimeError": RuntimeError("injected runtime failure"),
        "StopIteration": StopIteration("injected exhausted lookup"),
        "MemoryError": MemoryError("injected allocation failure"),
        "Refusal": wrkslots.Refusal("injected classification refusal"),
    }
    original_remove = wrkslots._cmd_remove
    attempted: list[str] = []

    def remove(
        args: argparse.Namespace,
        *,
        private_cleanup: wrkslots._PrivateCleanupContext | None = None,
        validation_removal_proof: wrkslots._ValidationRemovalProof | None = None,
        emit: bool = True,
    ) -> int:
        attempted.append(args.slot)
        if args.slot == "slot02" and kind == "symlink-loop":
            loop = wrkslots._slot_directory(config, "slot02", "agent") / "HANDOFF.md"
            assert not loop.exists() and not loop.is_symlink()
            loop.symlink_to(loop)
        elif args.slot == "slot02":
            if stage == "remove":
                raise errors[kind]
            raise wrkslots.Refusal("injected removal refusal")
        return original_remove(
            args,
            private_cleanup=private_cleanup,
            validation_removal_proof=validation_removal_proof,
            emit=emit,
        )

    def classify(*_args: object) -> tuple[str, str]:
        raise errors[kind]

    monkeypatch.setattr(wrkslots, "_cmd_remove", remove)
    if stage == "classification":
        monkeypatch.setattr(wrkslots, "_retirement_outcome_after_refusal", classify)
    code = _retire_two(project)

    assert attempted == ["slot01", "slot02"]
    assert code == 3
    payload = json.loads(capsys.readouterr().out)
    assert [row["slot"] for row in payload["removed"]] == ["slot01"]
    assert payload["retained"] == []
    assert payload["deferred"] == []
    assert payload["recovery_required"] is True
    [row] = payload["could_not_determine"]
    assert row["slot"] == "slot02"
    assert row["recovery_required"] is True
    if kind == "symlink-loop":
        assert row["reason"].startswith("RuntimeError: Symlink loop from "), row
    else:
        assert row["reason"] == (
            str(errors[kind]) if kind == "Refusal" else f"{kind}: {errors[kind]}"
        )


def test_retire_pending_reports_its_batch_when_the_machine_state_disappears(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
    capsys: pytest.CaptureFixture[str],
) -> None:
    """A machine missing when a refusal is classified stops the batch with its report.

    slot01 is removed.  slot02's removal deletes the machine's ACTIVE,
    ARCHIVED and EVENTS paths and refuses, so the real classifier finds no
    registry state for the machine.  The report keeps slot01's removal,
    stops at slot02, which needs recovery, and defers slot03.
    """

    project, _repository, _remote = _queue_two_finished_slots_with_dead_owners(
        tmp_path, monkeypatch, count=3
    )
    config = wrkslots._load_config(str(project), "testhost")
    original_remove = wrkslots._cmd_remove
    attempted: list[str] = []

    def remove(
        args: argparse.Namespace,
        *,
        private_cleanup: wrkslots._PrivateCleanupContext | None = None,
        validation_removal_proof: wrkslots._ValidationRemovalProof | None = None,
        emit: bool = True,
    ) -> int:
        attempted.append(args.slot)
        if args.slot == "slot02":
            wrkslots._active_path(config).unlink()
            wrkslots._archive_path(config).unlink()
            shutil.rmtree(wrkslots._event_directory(config))
            raise wrkslots.Refusal("injected removal refusal")
        return original_remove(
            args,
            private_cleanup=private_cleanup,
            validation_removal_proof=validation_removal_proof,
            emit=emit,
        )

    monkeypatch.setattr(wrkslots, "_cmd_remove", remove)
    code = wrkslots.main(
        [
            "--project-root",
            str(project),
            "retire-pending",
            "--limit",
            "3",
            "--coordinator-pid",
            str(os.getpid()),
            "--format",
            "json",
        ]
    )

    assert attempted == ["slot01", "slot02"]
    assert code == 3
    payload = json.loads(capsys.readouterr().out)
    assert [row["slot"] for row in payload["removed"]] == ["slot01"]
    assert payload["retained"] == []
    assert payload["recovery_required"] is True
    [row] = payload["could_not_determine"]
    assert row["slot"] == "slot02"
    assert row["recovery_required"] is True
    assert row["reason"] == (
        "retire-pending outcome=could-not-determine recovery_required=true: "
        "retirement attempt for slot02 found no registry state for machine testhost"
    )
    assert [item["slot"] for item in payload["deferred"]] == ["slot03"]
    assert payload["deferred"][0]["reason"] == (
        "batch stopped after an indeterminate retirement outcome"
    )


def _assert_retire_pending_stopped_at_slot01(
    payload: Mapping[str, object], reason: str
) -> None:
    assert payload["removed"] == []
    rows = payload["could_not_determine"]
    assert isinstance(rows, list) and len(rows) == 1
    [row] = rows
    assert isinstance(row, dict)
    assert row["slot"] == "slot01"
    assert row["recovery_required"] is True
    assert reason in row["reason"]
    assert "the batch continued" not in row["reason"]
    deferred = payload["deferred"]
    assert isinstance(deferred, list)
    assert [item["slot"] for item in deferred] == ["slot02"]
    assert deferred[0]["reason"] == (
        "batch stopped after an indeterminate retirement outcome"
    )


def test_retire_pending_stops_at_a_storage_drift_found_after_a_change(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
    capsys: pytest.CaptureFixture[str],
) -> None:
    """Drift that removal finds once it has written the registry stops the batch.

    The registration inside slot01 appears after removal's first storage
    check passed; its next check, at the destructive boundary, follows the
    ``checkout-evidence-refreshed`` write of the active state, so the
    attempt cannot be shown to have changed nothing.
    """

    project, repository, _remote = _queue_two_finished_slots_with_dead_owners(
        tmp_path, monkeypatch
    )
    nested = checkout(project, slot="slot01") / "ignored" / "nested"
    original = wrkslots._reclaim_preconditions

    def register_after_the_first_check(
        config: wrkslots.Config,
        record: wrkslots.ActiveRecord,
        vcs: wrkslots._GitVcs,
        finish_context: wrkslots._FinishContext,
        **options: bool,
    ) -> tuple[Path, tuple[wrkslots.Checkout, ...]]:
        found = original(config, record, vcs, finish_context, **options)
        if record.slot == "slot01" and not nested.exists():
            git(repository, "worktree", "add", "-b", "nested", str(nested))
        return found

    monkeypatch.setattr(
        wrkslots, "_reclaim_preconditions", register_after_the_first_check
    )

    code = _retire_two(project)

    assert code == 3
    payload = json.loads(capsys.readouterr().out)
    _assert_retire_pending_stopped_at_slot01(payload, str(nested))
    assert nested.is_dir()


def test_retire_pending_stops_when_a_drifted_row_changed_before_its_confirmation(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
    capsys: pytest.CaptureFixture[str],
) -> None:
    """The row must be exactly as the refused removal read it, not only the same generation."""

    project, repository, _remote = _queue_two_finished_slots_with_dead_owners(
        tmp_path, monkeypatch
    )
    nested = checkout(project, slot="slot01") / "ignored" / "nested"
    git(repository, "worktree", "add", "-b", "nested", str(nested))
    config = wrkslots._load_config(str(project), "testhost")
    original_remove = wrkslots._cmd_remove

    def drift_then_row_change(
        args: argparse.Namespace,
        *,
        private_cleanup: wrkslots._PrivateCleanupContext | None = None,
        validation_removal_proof: wrkslots._ValidationRemovalProof | None = None,
        emit: bool = True,
    ) -> int:
        try:
            return original_remove(
                args,
                private_cleanup=private_cleanup,
                validation_removal_proof=validation_removal_proof,
                emit=emit,
            )
        except wrkslots._TargetStorageDrift:
            state = wrkslots._load_active(config, require_repository=False)
            record = wrkslots._find_record(state, args.slot)
            wrkslots._write_active_state(
                config,
                wrkslots._replace_record(
                    state, replace(record, purpose="changed after the refusal")
                ),
                action="test-row-changed",
                slot=args.slot,
                require_repository=False,
            )
            raise

    monkeypatch.setattr(wrkslots, "_cmd_remove", drift_then_row_change)

    code = _retire_two(project)

    assert code == 3
    payload = json.loads(capsys.readouterr().out)
    _assert_retire_pending_stopped_at_slot01(
        payload, "no longer finds its exact active row after its storage refusal"
    )


def test_retire_pending_reports_its_batch_when_a_drift_confirmation_refuses(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
    capsys: pytest.CaptureFixture[str],
) -> None:
    """Any refusal while confirming a drifted target stops the batch with its report.

    slot01 is removed first; slot02's own storage drifts, and the
    confirmation then refuses as a configuration revalidation would.  The
    report still names slot01's removal.
    """

    project, repository, _remote = _queue_two_finished_slots_with_dead_owners(
        tmp_path, monkeypatch
    )
    nested = checkout(project, slot="slot02") / "ignored" / "nested"
    git(repository, "worktree", "add", "-b", "nested", str(nested))

    def refuse(*_args: object, **_kwargs: object) -> None:
        raise wrkslots.Refusal("injected configuration refusal")

    monkeypatch.setattr(
        wrkslots, "_confirm_unchanged_after_target_storage_drift", refuse
    )

    code = _retire_two(project)

    assert code == 3
    payload = json.loads(capsys.readouterr().out)
    assert [row["slot"] for row in payload["removed"]] == ["slot01"]
    [row] = payload["could_not_determine"]
    assert row["slot"] == "slot02"
    assert row["recovery_required"] is True
    assert str(nested) in row["reason"]
    assert "injected configuration refusal" in row["reason"]
    assert "the batch continued" not in row["reason"]
    assert payload["recovery_required"] is True
    assert nested.is_dir()


@pytest.mark.parametrize(
    ("fault", "error"),
    [
        pytest.param("undecodable-event", "UnicodeDecodeError", id="undecodable-event"),
        pytest.param("unreadable-event-log", "PermissionError", id="unreadable-event-log"),
        pytest.param("deeply-nested-event", "RecursionError", id="deeply-nested-event"),
    ],
)
def test_retire_pending_reports_its_batch_when_a_drift_confirmation_cannot_read(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
    capsys: pytest.CaptureFixture[str],
    fault: str,
    error: str,
) -> None:
    """A registry the confirmation cannot read or decode stops the batch with its report.

    slot01 is removed first; slot02's own storage drifts, and before the
    confirmation reads the registry again its event log gains the next event
    file holding bytes that are not UTF-8 (``undecodable-event``) or JSON
    nested ten thousand arrays deep (``deeply-nested-event``), or loses its
    read permission (``unreadable-event-log``).  None of these errors is a
    refusal of its own, and the report must still name slot01's removal.
    """

    if fault == "unreadable-event-log" and os.geteuid() == 0:
        pytest.skip("root reads a directory whatever its permission bits, so it is not unreadable")
    project, repository, _remote = _queue_two_finished_slots_with_dead_owners(
        tmp_path, monkeypatch
    )
    nested = checkout(project, slot="slot02") / "ignored" / "nested"
    git(repository, "worktree", "add", "-b", "nested", str(nested))
    config = wrkslots._load_config(str(project), "testhost")
    events = wrkslots._event_directory(config)
    original_remove = wrkslots._cmd_remove
    injected: list[str] = []

    def drift_then_fault(
        args: argparse.Namespace,
        *,
        private_cleanup: wrkslots._PrivateCleanupContext | None = None,
        validation_removal_proof: wrkslots._ValidationRemovalProof | None = None,
        emit: bool = True,
    ) -> int:
        try:
            return original_remove(
                args,
                private_cleanup=private_cleanup,
                validation_removal_proof=validation_removal_proof,
                emit=emit,
            )
        except wrkslots._TargetStorageDrift:
            if args.slot == "slot02":
                sequence = len(wrkslots._event_file_names(events)) + 1
                if fault == "undecodable-event":
                    (events / f"{sequence:020d}.json").write_bytes(b'{"schema": "\xff\xfe"}\n')
                elif fault == "deeply-nested-event":
                    nesting = b"[" * 10_000 + b"0" + b"]" * 10_000
                    (events / f"{sequence:020d}.json").write_bytes(
                        b'{"schema": ' + nesting + b"}\n"
                    )
                else:
                    events.chmod(0)
                injected.append(args.slot)
            raise

    monkeypatch.setattr(wrkslots, "_cmd_remove", drift_then_fault)
    try:
        code = _retire_two(project)
    finally:
        events.chmod(0o755)

    assert injected == ["slot02"]
    assert code == 3
    payload = json.loads(capsys.readouterr().out)
    assert [row["slot"] for row in payload["removed"]] == ["slot01"]
    [row] = payload["could_not_determine"]
    assert row["slot"] == "slot02"
    assert row["recovery_required"] is True
    assert str(nested) in row["reason"]
    assert f"cannot read the registry: {error}" in row["reason"]
    assert "the batch continued" not in row["reason"]
    assert payload["recovery_required"] is True
    assert nested.is_dir()


def test_finish_still_refuses_a_legacy_flat_handoff(tmp_path: Path) -> None:
    project, repository, _remote = make_project(
        tmp_path, worktrees_directory="worktrees/slots", layout="flat"
    )
    assert create(project).returncode == 0
    commit_task(repository, checkout(project), "codex/task")
    legacy = checkout(project) / "HANDOFF.md"
    legacy.write_text("legacy untracked work\n", encoding="utf-8")

    refused = finish(project)

    assert refused.returncode == 3
    assert "dirty or has untracked/ignored files" in refused.stderr
    assert "keep a handoff out of commits (use write-handoff)" in refused.stderr
    assert legacy.read_text(encoding="utf-8") == "legacy untracked work\n"


def test_read_handoff_ignores_unrelated_absent_ownerless_row(
    tmp_path: Path,
) -> None:
    project, repository, _remote = make_project(tmp_path)
    made = create(project)
    assert made.returncode == 0, made.stderr
    handoff = checkout(project).parent / "HANDOFF.md"
    contents = b"Continue from the exact recorded commit.\n"
    handoff.write_bytes(contents)

    unrelated_made = create(
        project,
        slot="unrelated",
        agent="unrelated-agent",
        branch="agent/unrelated",
        bind_owner=False,
    )
    assert unrelated_made.returncode == 0, unrelated_made.stderr
    config = wrkslots._load_config(str(project), "testhost")
    unrelated = wrkslots._find_record(wrkslots._load_active(config), "unrelated")
    shutil.rmtree(wrkslots._slot_directory(config, unrelated.slot, "agent"))
    assert unrelated.owner is None
    assert unrelated.checkouts[0].path in {
        path.relative_to(project).as_posix()
        for path in wrkslots._GitVcs().listed_worktrees(repository)
    }
    before = wrkslots._record_to_obj(unrelated)

    read = raw_command(
        project,
        "read-handoff",
        "slot01",
        "--coordinator-pid",
        str(os.getpid()),
    )

    assert read.returncode == 0, read.stderr
    assert "Continue from the exact recorded commit." in read.stdout
    after = wrkslots._find_record(wrkslots._load_active(config), "unrelated")
    assert wrkslots._record_to_obj(after) == before
    events = wrkslots._load_events(config)
    read_events = [event for event in events if event["kind"] == "handoff-read"]
    assert len(read_events) == 2
    assert [
        wrkslots._as_mapping(event["payload"], "handoff read payload")[
            "retirement_enqueued"
        ]
        for event in read_events
    ] == [False, True]
    payload = wrkslots._as_mapping(read_events[-1]["payload"], "handoff read payload")
    assert payload["slot"] == "slot01"
    assert payload["sha256"] == hashlib.sha256(contents).hexdigest()


