def test_failing_setup_hooks_installer_is_reported_and_creation_stands(
    tmp_path: Path,
) -> None:
    project, repository, _remote = make_project(tmp_path)
    add_installer_submodule(
        tmp_path,
        project,
        repository,
        "#!/bin/sh\necho installer-stdout-line\necho installer-stderr-line >&2\nexit 7\n",
    )

    made = create(project)

    assert made.returncode == 0, made.stderr
    assert len(active_slots(project)) == 1
    submodule = checkout(project) / "hooked"
    assert (
        f"hooks: WARNING scripts/setup-hooks.sh in {submodule} failed (rc 7); "
        "the slot was created without these Git hooks"
    ) in made.stdout
    assert "hooks: | installer-stdout-line" in made.stdout
    assert "hooks: | installer-stderr-line" in made.stdout

    made_json = raw_command(
        project,
        "create",
        "slot02",
        "--format",
        "json",
        "--slot-type",
        "agent",
        "--coordinator-authorized",
        "--agent",
        "codex-2",
        "--task",
        "task-slot02",
        "--purpose",
        "test slot02",
        "--owner-pid",
        str(os.getpid()),
        "--coordinator-pid",
        str(os.getpid()),
        "--repo",
        "product=repo",
        "--branch",
        "product=codex/task2",
    )

    assert made_json.returncode == 0, made_json.stderr
    assert len(active_slots(project)) == 2
    payload = json.loads(made_json.stdout)
    results = payload["setup_hooks"]["results"]
    assert payload["setup_hooks"]["repositories_checked"] == 2
    assert [(item["status"], item["returncode"]) for item in results] == [("failed", 7)]
    assert results[0]["path"] == str(checkout(project, "slot02") / "hooked")
    assert results[0]["output_tail"] == "installer-stdout-line\ninstaller-stderr-line"
    assert "failed (rc 7)" in made_json.stderr


def test_setup_hooks_installer_is_stopped_at_its_time_bound(
    tmp_path: Path, monkeypatch: pytest.MonkeyPatch
) -> None:
    repository = tmp_path / "repository"
    installer = repository / "scripts" / "setup-hooks.sh"
    installer.parent.mkdir(parents=True)
    installer.write_text("#!/bin/sh\necho started\nexec sleep 30\n", encoding="utf-8")
    installer.chmod(0o755)
    monkeypatch.setattr(wrkslots, "SETUP_HOOKS_TIMEOUT_SECONDS", 0.5)

    started = time.monotonic()
    result = wrkslots._run_one_setup_hook_installer(repository)

    assert time.monotonic() - started < 10
    assert result.status == "timed-out"
    assert result.output_tail == "started"
    assert result.returncode is not None and result.returncode < 0


def test_setup_hooks_output_file_failure_is_a_result_not_a_raise(
    tmp_path: Path, monkeypatch: pytest.MonkeyPatch
) -> None:
    repository = tmp_path / "repository"
    marker = tmp_path / "ran"
    installer = repository / "scripts" / "setup-hooks.sh"
    installer.parent.mkdir(parents=True)
    installer.write_text(f"#!/bin/sh\ntouch {marker}\n", encoding="utf-8")
    installer.chmod(0o755)

    def no_space(*_args: object, **_kwargs: object) -> object:
        raise OSError(errno.ENOSPC, "No space left on device")

    monkeypatch.setattr(tempfile, "TemporaryFile", no_space)

    result = wrkslots._run_one_setup_hook_installer(repository)

    assert result.status == "failed-to-start"
    assert "cannot create its output file" in result.detail
    assert "No space left on device" in result.detail
    assert not marker.exists()


def test_failed_post_provision_hook_is_loud_and_recovery_resumes_hooks(
    tmp_path: Path,
) -> None:
    project_path = tmp_path / "project"
    attempts = project_path / "hook-attempts"
    allow = project_path / "allow-hook"
    first = python_hook(
        "from pathlib import Path; "
        f"p = Path({str(attempts)!r}); "
        "p.write_text(p.read_text() + 'first\\n' if p.exists() else 'first\\n')"
    )
    failing = python_hook(
        "import sys; from pathlib import Path; "
        f"p = Path({str(attempts)!r}); "
        "p.write_text(p.read_text() + 'second\\n'); "
        "Path('target').mkdir(exist_ok=True); "
        "Path('target/generated').write_text('cache'); "
        "print('hook stdout evidence'); "
        "print('hook stderr evidence', file=sys.stderr); "
        f"raise SystemExit(0 if Path({str(allow)!r}).exists() else 17)"
    )
    project, repository, _remote = make_project(
        tmp_path,
        worktrees_directory="worktrees/slots",
        layout="flat",
        cache_globs=("target",),
        post_provision_hooks=(first, failing),
    )

    refused = create(project)

    assert refused.returncode == 3
    output = refused.stdout + refused.stderr
    assert "hook stdout evidence" in output
    assert "hook stderr evidence" in output
    assert "17" in output
    assert "recover" in output.lower()
    assert checkout(project).is_dir()
    assert active_slots(project) == []
    journal = create_journal_path(project)
    assert journal.is_file()
    assert attempts.read_text(encoding="utf-8") == "first\nsecond\n"
    audit = command(project, "audit", "--format", "json")
    assert audit.returncode == 0, audit.stderr
    audit_row = json.loads(audit.stdout)["slots"][0]
    assert audit_row["slot"] == "slot01"
    assert audit_row["owner_state"] == "create-journal"
    assert "wrkslots recover" in audit_row["reasons"][0]
    git(checkout(project), "checkout", "-b", "scratch/cache-cleanup")
    reclaimed = command(project, "clean-caches", "--only", "slot01")
    assert reclaimed.returncode == 0, reclaimed.stderr
    assert not (checkout(project) / "target").exists()
    assert journal.is_file()
    git(checkout(project), "checkout", "codex/task")

    allow.write_text("retry may proceed\n", encoding="utf-8")
    interrupted_state = json.loads(journal.read_text(encoding="utf-8"))
    legacy = control_directory(project) / "ACTIVE.testhost.journal"
    os.replace(journal, legacy)
    journal = legacy
    shutil.rmtree(control_directory(project) / "EVENTS.testhost")
    interrupted_state["hook_progress"] = 2
    journal.write_text(
        json.dumps(interrupted_state, indent=2, sort_keys=True) + "\n",
        encoding="utf-8",
    )
    inconsistent = command(
        project,
        "recover",
        "--coordinator-pid",
        str(os.getpid()),
    )
    assert inconsistent.returncode == 3
    assert "hook" in inconsistent.stderr.lower()
    assert active_slots(project) == []

    interrupted_state["hook_progress"] = 1
    interrupted_state["hook_failure"]["status"] = "running"
    del interrupted_state["hook_failure"]["returncode"]
    journal.write_text(
        json.dumps(interrupted_state, indent=2, sort_keys=True) + "\n",
        encoding="utf-8",
    )
    ambiguous = command(
        project,
        "recover",
        "--coordinator-pid",
        str(os.getpid()),
    )
    assert ambiguous.returncode == 3
    assert "--retry-running-hook" in ambiguous.stderr
    assert attempts.read_text(encoding="utf-8") == "first\nsecond\n"

    recovered = command(
        project,
        "recover",
        "--coordinator-pid",
        str(os.getpid()),
        "--retry-running-hook",
    )

    assert recovered.returncode == 0, recovered.stderr
    assert len(active_slots(project)) == 1
    assert not journal.exists()
    assert attempts.read_text(encoding="utf-8") == "first\nsecond\nsecond\n"


# Measured 2026-09-26 on a host with 4,300 processes: 8 s once the census walks
# each distinct mount table once, 41 s before; a gate that timed out spent over
# 40 s of CPU in one such abort.  This is a coarse backstop with room for a
# loaded gate; the deterministic guard is the work count in test_census_cost.py.
REAL_CENSUS_ABORT_SECONDS = 60


def test_failed_post_provision_hook_can_be_explicitly_aborted(
    tmp_path: Path,
) -> None:
    """The deliberate `--abort-create` through the real host-wide slot-use census.

    Tests of the create journal stub that census; this one keeps it, under a
    bound, so a census that again costs minutes per abort fails here by name
    rather than by timing out the whole component step.  The bound kills only
    the wrkslots process, not any helper it has started.
    """

    project, repository, _remote = make_project(
        tmp_path,
        worktrees_directory="worktrees/slots",
        layout="flat",
        post_provision_hooks=("exit 9",),
    )
    refused = create(project)
    assert refused.returncode == 3
    journal = create_journal_path(project)
    assert journal.is_file()
    assert checkout(project).is_dir()

    aborted = command(
        project,
        "recover",
        "--coordinator-pid",
        str(os.getpid()),
        "--abort-create",
        timeout=REAL_CENSUS_ABORT_SECONDS,
    )

    assert aborted.returncode == 0, aborted.stderr
    assert active_slots(project) == []
    assert not checkout(project).exists()
    assert not journal.exists()
    assert git(
        repository,
        "show-ref",
        "--verify",
        "--quiet",
        "refs/heads/codex/task",
        check=False,
    ).returncode == 1


def prepare_failed_create_with_empty_submodule_administration(
    tmp_path: Path,
) -> tuple[Path, Path, Path, Path, Path]:
    project, repository, _remote = make_project(tmp_path)
    add_recursive_submodules(tmp_path, project, repository)
    update_configuration(
        project,
        post_provision_hooks=["exit 9"],
    )

    refused = create(project)

    assert refused.returncode == 3
    tree = checkout(project)
    journal = create_journal_path(project)
    assert tree.is_dir()
    assert journal.is_file()
    git_directory = Path(
        git(
            tree,
            "rev-parse",
            "--path-format=absolute",
            "--git-dir",
        ).stdout.strip()
    )
    administration = git_directory / "modules"
    (administration / "third-party").mkdir(parents=True)
    submodules = git(tree, "submodule", "status", "--recursive").stdout.splitlines()
    assert submodules
    assert all(line.startswith("-") for line in submodules)
    assert git(tree, "status", "--porcelain=v2", "--untracked-files=all").stdout == ""
    refused_by_git = git(
        repository,
        "worktree",
        "remove",
        "--",
        str(tree),
        check=False,
    )
    assert refused_by_git.returncode != 0
    assert "containing submodules cannot be moved or removed" in refused_by_git.stderr
    assert tree.is_dir()
    return project, repository, tree, journal, administration


def test_abort_create_removes_clean_worktree_with_uninitialized_submodule(
    tmp_path: Path,
) -> None:
    project, repository, tree, journal, administration = (
        prepare_failed_create_with_empty_submodule_administration(tmp_path)
    )
    common = Path(
        git(
            repository,
            "rev-parse",
            "--path-format=absolute",
            "--git-common-dir",
        ).stdout.strip()
    )
    config_before = (common / "config").read_bytes()
    source_submodules_before = git(
        repository, "submodule", "status", "--recursive"
    ).stdout
    assert sorted(
        path.relative_to(administration)
        for path in administration.rglob("*")
    ) == [Path("third-party")]

    aborted = command(
        project,
        "recover",
        "--coordinator-pid",
        str(os.getpid()),
        "--abort-create",
    )

    assert aborted.returncode == 0, aborted.stderr
    assert not tree.exists()
    assert not journal.exists()
    assert active_slots(project) == []
    assert (common / "config").read_bytes() == config_before
    assert (
        git(repository, "submodule", "status", "--recursive").stdout
        == source_submodules_before
    )
    assert (
        git(
            repository,
            "show-ref",
            "--verify",
            "--quiet",
            "refs/heads/codex/task",
            check=False,
        ).returncode
        == 1
    )


@pytest.mark.parametrize(
    ("mutation", "message"),
    (
        ("dirty", "source state is dirty"),
        ("moved", "cannot abort changed checkout"),
        ("operation", "unfinished Git operation"),
        ("identity", "does not belong to repository"),
        ("initialized-clean", "initialized submodule"),
        ("nested-dirty-hidden", "initialized submodule"),
        ("deinitialized-unique-commit", "non-directory entry"),
        ("deinitialized-unique-branch", "non-directory entry"),
        ("deinitialized-stash", "non-directory entry"),
        ("initialized-ignored-file", "initialized submodule"),
        ("admin-file", "non-directory entry"),
        ("admin-symlink", "contains a symlink"),
        ("admin-directory-count", "directory-count bound"),
        ("admin-directory-depth", "directory-depth bound"),
    ),
)
def test_abort_create_empty_admin_prune_preserves_every_preflight_refusal(
    tmp_path: Path, mutation: str, message: str
) -> None:
    project, repository, tree, journal, administration = (
        prepare_failed_create_with_empty_submodule_administration(tmp_path)
    )
    journal_before = journal.read_bytes()
    displaced = tmp_path / "displaced-worktree"
    displaced_admin = tmp_path / "displaced-admin"
    evidence: Path | None = None
    module_git_directory: Path | None = None
    preserved_object: str | None = None
    preserved_ref: str | None = None
    if mutation == "dirty":
        evidence = tree / "preserve.txt"
        evidence.write_text("preserve me\n", encoding="utf-8")
    elif mutation in {
        "initialized-clean",
        "nested-dirty-hidden",
        "deinitialized-unique-commit",
        "deinitialized-unique-branch",
        "deinitialized-stash",
        "initialized-ignored-file",
    }:
        git(
            tree,
            "-c",
            "protocol.file.allow=always",
            "submodule",
            "update",
            "--init",
            "--recursive",
        )
        component = tree / "component"
        leaf = component / "leaf"
        module_git_directory = Path(
            git(
                component,
                "rev-parse",
                "--path-format=absolute",
                "--git-dir",
            ).stdout.strip()
        )
        git(component, "config", "user.name", "Wrkslots Test")
        git(component, "config", "user.email", "wrkslots@example.invalid")
        if mutation == "nested-dirty-hidden":
            git(component, "config", "submodule.leaf.ignore", "all")
            evidence = leaf / "leaf.txt"
            evidence.write_text("nested work to preserve\n", encoding="utf-8")
            assert (
                git(
                    tree,
                    "status",
                    "--porcelain=v2",
                    "--untracked-files=all",
                    "--ignore-submodules=none",
                ).stdout
                == ""
            )
        elif mutation == "deinitialized-unique-commit":
            original = git(component, "rev-parse", "HEAD").stdout.strip()
            git(component, "switch", "--detach")
            evidence = component / "component.txt"
            evidence.write_text("unique detached work\n", encoding="utf-8")
            git(component, "commit", "-am", "unique detached work")
            preserved_object = git(component, "rev-parse", "HEAD").stdout.strip()
            git(component, "switch", "--detach", original)
            git(tree, "submodule", "deinit", "--force", "--all")
            evidence = module_git_directory / "objects"
        elif mutation == "deinitialized-unique-branch":
            preserved_ref = "refs/heads/preserve-local-work"
            git(component, "branch", "preserve-local-work")
            git(tree, "submodule", "deinit", "--force", "--all")
            evidence = module_git_directory / "refs"
        elif mutation == "deinitialized-stash":
            changed = component / "component.txt"
            changed.write_text("stash work to preserve\n", encoding="utf-8")
            git(component, "stash", "push", "-m", "preserve-stash")
            preserved_ref = "refs/stash"
            preserved_object = git(
                component, "rev-parse", preserved_ref
            ).stdout.strip()
            git(tree, "submodule", "deinit", "--force", "--all")
            evidence = module_git_directory / "logs"
        elif mutation == "initialized-ignored-file":
            exclude = Path(
                git(
                    component,
                    "rev-parse",
                    "--path-format=absolute",
                    "--git-path",
                    "info/exclude",
                ).stdout.strip()
            )
            exclude.write_text("preserve.log\n", encoding="utf-8")
            evidence = component / "preserve.log"
            evidence.write_text("ignored evidence\n", encoding="utf-8")
            assert "preserve.log" in git(
                component,
                "status",
                "--porcelain=v2",
                "--untracked-files=all",
                "--ignored=matching",
            ).stdout
        else:
            assert mutation == "initialized-clean"
        assert (
            git(tree, "status", "--porcelain=v2", "--untracked-files=all").stdout
            == ""
        )
    elif mutation == "moved":
        git(tree, "commit", "--allow-empty", "-m", "move aborted checkout")
    elif mutation == "operation":
        evidence = Path(
            git(tree, "rev-parse", "--git-path", "MERGE_HEAD").stdout.strip()
        )
        evidence.write_text(
            git(tree, "rev-parse", "HEAD").stdout,
            encoding="utf-8",
        )
    elif mutation == "identity":
        tree.rename(displaced)
        subprocess.run(
            ["git", "clone", str(repository), str(tree)],
            check=True,
            capture_output=True,
            text=True,
        )
    elif mutation == "admin-file":
        evidence = administration / "third-party" / "preserve.admin"
        evidence.write_text("administrative evidence\n", encoding="utf-8")
    elif mutation == "admin-symlink":
        (administration / "third-party").rmdir()
        displaced_admin.mkdir()
        (administration / "third-party").symlink_to(
            displaced_admin, target_is_directory=True
        )
        evidence = displaced_admin
    elif mutation == "admin-directory-count":
        for index in range(wrkslots._EMPTY_SUBMODULE_ADMIN_DIRECTORY_LIMIT - 1):
            (administration / f"bounded-{index:04d}").mkdir()
        evidence = administration / "bounded-0000"
    else:
        assert mutation == "admin-directory-depth"
        evidence = administration / "third-party"
        for index in range(wrkslots._EMPTY_SUBMODULE_ADMIN_DEPTH_LIMIT):
            evidence /= f"nested-{index:02d}"
            evidence.mkdir()

    branch_before = git(
        repository, "rev-parse", "refs/heads/codex/task"
    ).stdout.strip()
    aborted = command(
        project,
        "recover",
        "--coordinator-pid",
        str(os.getpid()),
        "--abort-create",
    )

    assert aborted.returncode == 3
    assert message in aborted.stderr
    assert tree.is_dir()
    assert journal.read_bytes() == journal_before
    assert active_slots(project) == []
    assert str(tree) in git(repository, "worktree", "list", "--porcelain").stdout
    assert (
        git(repository, "rev-parse", "refs/heads/codex/task").stdout.strip()
        == branch_before
    )
    if evidence is not None:
        assert evidence.exists()
    if mutation == "identity":
        assert displaced.is_dir()
    if module_git_directory is not None:
        assert module_git_directory.is_dir()
    if preserved_object is not None:
        assert (
            git_dir(
                cast(Path, module_git_directory),
                "cat-file",
                "-e",
                f"{preserved_object}^{{commit}}",
                check=False,
            ).returncode
            == 0
        )
    if preserved_ref is not None:
        assert (
            git_dir(
                cast(Path, module_git_directory),
                "show-ref",
                "--verify",
                "--quiet",
                preserved_ref,
                check=False,
            ).returncode
            == 0
        )


@pytest.mark.parametrize("race", ("new-content", "replacement"))
def test_abort_create_empty_admin_prune_refuses_race_without_losing_evidence(
    tmp_path: Path, monkeypatch: pytest.MonkeyPatch, race: str
) -> None:
    project, repository, tree, journal, administration = (
        prepare_failed_create_with_empty_submodule_administration(tmp_path)
    )
    journal_before = journal.read_bytes()
    target = administration / "third-party"
    displaced = tmp_path / "raced-original-admin"
    original = wrkslots._rmdir_verified_empty_admin_directory
    injected = False

    def inject(
        parent_fd: int,
        directory_fd: int,
        name: str,
        path: Path,
        expected_identity: tuple[int, int, int],
    ) -> None:
        nonlocal injected
        if not injected and path == target:
            injected = True
            if race == "new-content":
                (path / "raced.txt").write_text(
                    "preserve raced content\n", encoding="utf-8"
                )
            else:
                path.rename(displaced)
                path.mkdir()
        original(parent_fd, directory_fd, name, path, expected_identity)

    monkeypatch.setattr(
        wrkslots, "_rmdir_verified_empty_admin_directory", inject
    )
    stdout = io.StringIO()
    stderr = io.StringIO()
    with contextlib.redirect_stdout(stdout), contextlib.redirect_stderr(stderr):
        returncode = wrkslots.main(
            [
                "--project-root",
                str(project),
                "recover",
                "--coordinator-pid",
                str(os.getpid()),
                "--abort-create",
                "--coordinator-authorized",
            ]
        )

    assert injected
    assert returncode == 3
    assert "submodule administration changed" in stderr.getvalue()
    assert tree.is_dir()
    assert journal.read_bytes() == journal_before
    assert str(tree) in git(repository, "worktree", "list", "--porcelain").stdout
    if race == "new-content":
        assert (target / "raced.txt").read_text(encoding="utf-8") == (
            "preserve raced content\n"
        )
    else:
        assert target.is_dir()
        assert displaced.is_dir()


@pytest.mark.parametrize("kind", ("cwd", "fd"))
def test_abort_create_empty_admin_prune_refuses_live_directory_holder(
    tmp_path: Path, kind: str
) -> None:
    project, repository, tree, journal, administration = (
        prepare_failed_create_with_empty_submodule_administration(tmp_path)
    )
    journal_before = journal.read_bytes()
    target = administration / "third-party"
    script = (
        "import os, pathlib, sys, time; "
        "path = pathlib.Path(sys.argv[1]); "
        + (
            "os.chdir(path); "
            if kind == "cwd"
            else "descriptor = os.open(path, os.O_RDONLY | os.O_DIRECTORY); "
        )
        + "print('ready', flush=True); time.sleep(300)"
    )
    holder = subprocess.Popen(
        [sys.executable, "-c", script, str(target)],
        stdout=subprocess.PIPE,
        stderr=subprocess.PIPE,
        text=True,
    )
    try:
        assert holder.stdout is not None
        assert holder.stdout.readline().strip() == "ready"
        refused = command(
            project,
            "recover",
            "--coordinator-pid",
            str(os.getpid()),
            "--abort-create",
        )
    finally:
        holder.terminate()
        holder.wait(timeout=5)

    assert refused.returncode == 3
    assert f"live process {holder.pid} uses slot {administration}" in refused.stderr
    assert tree.is_dir()
    assert target.is_dir()
    assert journal.read_bytes() == journal_before
    assert str(tree) in git(repository, "worktree", "list", "--porcelain").stdout


def test_abort_create_empty_admin_recheck_catches_late_holder(
    tmp_path: Path, monkeypatch: pytest.MonkeyPatch
) -> None:
    project, repository, tree, journal, administration = (
        prepare_failed_create_with_empty_submodule_administration(tmp_path)
    )
    journal_before = journal.read_bytes()
    target = administration / "third-party"
    original = wrkslots._assert_slot_unused
    holder: subprocess.Popen[str] | None = None

    def check_then_enter(path: Path) -> None:
        nonlocal holder
        original(path)
        if path == administration and holder is None:
            holder = subprocess.Popen(
                [
                    sys.executable,
                    "-c",
                    "import os, sys, time; os.chdir(sys.argv[1]); "
                    "print('ready', flush=True); time.sleep(300)",
                    str(target),
                ],
                stdout=subprocess.PIPE,
                stderr=subprocess.PIPE,
                text=True,
            )
            assert holder.stdout is not None
            assert holder.stdout.readline().strip() == "ready"

    monkeypatch.setattr(wrkslots, "_assert_slot_unused", check_then_enter)
    stdout = io.StringIO()
    stderr = io.StringIO()
    try:
        with contextlib.redirect_stdout(stdout), contextlib.redirect_stderr(stderr):
            returncode = wrkslots.main(
                [
                    "--project-root",
                    str(project),
                    "recover",
                    "--coordinator-pid",
                    str(os.getpid()),
                    "--abort-create",
                    "--coordinator-authorized",
                ]
            )
    finally:
        if holder is not None:
            holder.terminate()
            holder.wait(timeout=5)

    assert holder is not None
    assert returncode == 3
    assert f"live process {holder.pid} uses slot {administration}" in stderr.getvalue()
    assert tree.is_dir()
    assert target.is_dir()
    assert journal.read_bytes() == journal_before
    assert str(tree) in git(repository, "worktree", "list", "--porcelain").stdout


def test_abort_create_ordinary_git_remove_preserves_last_moment_dirty_file(
    tmp_path: Path, monkeypatch: pytest.MonkeyPatch
) -> None:
    project, repository, tree, journal, _administration = (
        prepare_failed_create_with_empty_submodule_administration(tmp_path)
    )
    journal_before = journal.read_bytes()
    evidence = tree / "late-evidence.txt"
    original = wrkslots._GitVcs.remove_worktree

    def dirty_then_remove(
        vcs: wrkslots._GitVcs,
        source: Path,
        checkout_path: Path,
        *,
        force: bool = False,
    ) -> None:
        assert not force
        evidence.write_text("late evidence\n", encoding="utf-8")
        original(vcs, source, checkout_path, force=force)

    monkeypatch.setattr(wrkslots._GitVcs, "remove_worktree", dirty_then_remove)
    stdout = io.StringIO()
    stderr = io.StringIO()
    with contextlib.redirect_stdout(stdout), contextlib.redirect_stderr(stderr):
        returncode = wrkslots.main(
            [
                "--project-root",
                str(project),
                "recover",
                "--coordinator-pid",
                str(os.getpid()),
                "--abort-create",
                "--coordinator-authorized",
            ]
        )

    assert returncode == 3
    assert "contains modified or untracked files" in stderr.getvalue()
    assert evidence.read_text(encoding="utf-8") == "late evidence\n"
    assert tree.is_dir()
    assert journal.read_bytes() == journal_before
    assert str(tree) in git(repository, "worktree", "list", "--porcelain").stdout


def test_audit_associates_recovery_journals_from_other_machine_shards(
    tmp_path: Path,
) -> None:
    project, repository, _remote = make_project(
        tmp_path,
        post_provision_hooks=("exit 9",),
    )
    refused = create(project, machine="otherhost")
    assert refused.returncode == 3

    audit = command(project, "audit", "--format", "json")

    assert audit.returncode == 0, audit.stderr
    row = json.loads(audit.stdout)["slots"][0]
    assert row["slot"] == "slot01"
    assert row["machine"] == "otherhost"
    assert row["owner_state"] == "create-journal"
    assert "wrkslots recover" in row["reasons"][0]

    git(repository, "worktree", "remove", "--force", str(checkout(project)))
    without_directory = command(project, "audit", "--format", "json")
    assert without_directory.returncode == 0, without_directory.stderr
    missing_row = json.loads(without_directory.stdout)["slots"][0]
    assert missing_row["slot"] == "slot01"
    assert missing_row["owner_state"] == "create-journal"


def test_audit_blocks_exact_validation_batch_seal_target(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
    capsys: pytest.CaptureFixture[str],
) -> None:
    project, _repository, _remote = make_project(tmp_path)
    prepare_dead_validate_slots(project, ("slot01",))
    config = wrkslots._load_config(str(project), "testhost")
    monkeypatch.setattr(
        wrkslots,
        "_capture_process_path_census",
        lambda _paths: wrkslots._ProcessPathCensus((), ()),
    )
    interrupted = raw_command(
        project,
        "remove-validate-batch",
        "--coordinator-pid",
        str(os.getpid()),
        "--slot",
        "slot01=1",
        env={"WRKSLOTS_TEST_INTERRUPT": "after-validate-batch-seal-target"},
    )
    assert interrupted.returncode == 86, interrupted.stderr
    active_before = wrkslots._active_path(config).read_bytes()
    seal_path = wrkslots._validate_batch_seal_journal_path(config)
    seal_before = seal_path.read_bytes()
    assert (
        wrkslots.main(
            ["--project-root", str(project), "audit", "--gate", "--format", "json"]
        )
        == 1
    )
    payload = json.loads(capsys.readouterr().out)
    row = next(row for row in payload["slots"] if row["slot"] == "slot01")
    assert row["verdict"] == "BLOCKED"
    assert "validation-batch seal" in row["reasons"][0]
    assert wrkslots._active_path(config).read_bytes() == active_before
    assert seal_path.read_bytes() == seal_before


def test_audit_reports_malformed_validation_batch_seal_as_unknown(
    tmp_path: Path,
    capsys: pytest.CaptureFixture[str],
) -> None:
    project, _repository, _remote = make_project(tmp_path)
    config = wrkslots._load_config(str(project), "testhost")
    seal_path = wrkslots._validate_batch_seal_journal_path(config)
    seal_path.write_text("{not-json\n", encoding="utf-8")
    before = seal_path.read_bytes()

    assert (
        wrkslots.main(
            ["--project-root", str(project), "audit", "--gate", "--format", "json"]
        )
        == 2
    )
    payload = json.loads(capsys.readouterr().out)
    row = next(row for row in payload["slots"] if row["slot"] == seal_path.name)
    assert row["verdict"] == "UNKNOWN"
    assert "seal evidence is unreadable" in row["reasons"][0]
    assert seal_path.read_bytes() == before


def test_audit_reports_unattributable_validation_batch_seal_as_unknown(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
    capsys: pytest.CaptureFixture[str],
) -> None:
    project, _repository, _remote = make_project(tmp_path)
    prepare_dead_validate_slots(project, ("slot01",))
    config = wrkslots._load_config(str(project), "testhost")
    monkeypatch.setattr(
        wrkslots,
        "_capture_process_path_census",
        lambda _paths: wrkslots._ProcessPathCensus((), ()),
    )
    interrupted = raw_command(
        project,
        "remove-validate-batch",
        "--coordinator-pid",
        str(os.getpid()),
        "--slot",
        "slot01=1",
        env={"WRKSLOTS_TEST_INTERRUPT": "after-validate-batch-seal-target"},
    )
    assert interrupted.returncode == 86, interrupted.stderr
    seal_path = wrkslots._validate_batch_seal_journal_path(config)
    seal = json.loads(seal_path.read_text(encoding="utf-8"))
    seal["targets"][0]["generation"] = 2
    seal_path.write_text(json.dumps(seal, indent=2) + "\n", encoding="utf-8")
    before = seal_path.read_bytes()
    assert (
        wrkslots.main(
            ["--project-root", str(project), "audit", "--gate", "--format", "json"]
        )
        == 2
    )
    payload = json.loads(capsys.readouterr().out)
    row = next(row for row in payload["slots"] if row["slot"] == "slot01")
    assert row["verdict"] == "UNKNOWN"
    assert "cannot be attributed" in row["reasons"][0]
    assert seal_path.read_bytes() == before


def test_abort_create_preflights_every_checkout_before_removing_any(
    tmp_path: Path,
) -> None:
    project, repository, remote = make_project(
        tmp_path,
        post_provision_hooks=("exit 9",),
    )
    second_repository = project / "repo-two"
    subprocess.run(
        ["git", "clone", str(remote), str(second_repository)],
        check=True,
        capture_output=True,
        text=True,
    )
    remote_url = git(repository, "remote", "get-url", "origin").stdout.strip()
    made = command(
        project,
        "create",
        "slot01",
        "--agent",
        "codex-1",
        "--task",
        "task-abort",
        "--purpose",
        "abort preflight",
        "--owner-pid",
        str(os.getpid()),
        "--coordinator-pid",
        str(os.getpid()),
        "--repo",
        "first=repo",
        "--remote-url",
        f"first={remote_url}",
        "--branch",
        "first=codex/first-abort",
        "--repo",
        "second=repo-two",
        "--remote-url",
        f"second={remote_url}",
        "--branch",
        "second=codex/second-abort",
    )
    assert made.returncode == 3
    first = checkout(project, name="first")
    second = checkout(project, name="second")
    evidence = second / "hook-notes.txt"
    evidence.write_text("preserve me\n", encoding="utf-8")

    aborted = command(
        project,
        "recover",
        "--coordinator-pid",
        str(os.getpid()),
        "--abort-create",
    )

    assert aborted.returncode == 3
    assert "source state is dirty" in aborted.stderr
    assert first.is_dir()
    assert second.is_dir()
    assert evidence.read_text(encoding="utf-8") == "preserve me\n"


def test_abort_create_refuses_and_preserves_untracked_source_from_failed_hook(
    tmp_path: Path,
) -> None:
    failing = python_hook(
        "from pathlib import Path; "
        "Path('important-source.txt').write_text('preserve me\\n'); "
        "raise SystemExit(9)"
    )
    project, repository, _remote = make_project(
        tmp_path,
        worktrees_directory="worktrees/slots",
        layout="flat",
        post_provision_hooks=(failing,),
    )
    refused = create(project)
    assert refused.returncode == 3
    tree = checkout(project)
    source = tree / "important-source.txt"
    journal = create_journal_path(project)
    assert source.read_text(encoding="utf-8") == "preserve me\n"

    aborted = command(
        project,
        "recover",
        "--coordinator-pid",
        str(os.getpid()),
        "--abort-create",
    )

    assert aborted.returncode == 3
    assert "source state is dirty" in aborted.stderr
    assert source.read_text(encoding="utf-8") == "preserve me\n"
    assert tree.is_dir()
    assert journal.is_file()
    assert git(
        repository,
        "show-ref",
        "--verify",
        "--quiet",
        "refs/heads/codex/task",
        check=False,
    ).returncode == 0


def test_disk_ladder_warns_refuses_allows_override_and_keeps_emergency_hard(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
    capsys: pytest.CaptureFixture[str],
) -> None:
    gib = 1024**3
    project, repository, _remote = make_project(
        tmp_path,
        disk_thresholds_gib=(250, 200, 100),
    )
    config = configuration(project)
    assert config["disk_advisory_bytes"] == 250 * gib
    assert config["disk_provisioning_floor_bytes"] == 200 * gib
    assert config["disk_emergency_bytes"] == 100 * gib
    remote_url = git(repository, "remote", "get-url", "origin").stdout.strip()

    def run_create(
        slot: str, agent: str, branch: str, *, override: bool = False
    ) -> tuple[int, str]:
        argv = [
            "--project-root",
            str(project),
            "create",
            slot,
            "--slot-type",
            "agent",
            "--coordinator-authorized",
            "--agent",
            agent,
            "--task",
            f"task-{slot}",
            "--purpose",
            f"disk policy {slot}",
            "--owner-pid",
            str(os.getpid()),
            "--coordinator-pid",
            str(os.getpid()),
            "--repo",
            "product=repo",
            "--remote-url",
            f"product={remote_url}",
            "--branch",
            f"product={branch}",
        ]
        if override:
            argv.append("--override-disk-floor")
        code = wrkslots.main(argv)
        captured = capsys.readouterr()
        return code, captured.out + captured.err

    monkeypatch.setattr(wrkslots, "_free_bytes", lambda _path: 225 * gib)
    advisory_code, advisory_output = run_create(
        "slot01", "codex-1", "codex/advisory"
    )

    assert advisory_code == 0, advisory_output
    assert "advisory" in advisory_output.lower()

    monkeypatch.setattr(wrkslots, "_free_bytes", lambda _path: 150 * gib)
    floor_code, floor_output = run_create(
        "slot02", "codex-2", "codex/floor"
    )

    assert floor_code == 3
    assert "provision" in floor_output.lower()
    assert "audit" in floor_output.lower()
    assert "clean-caches" in floor_output.lower()
    assert not checkout(project, "slot02").exists()

    override_code, override_output = run_create(
        "slot02", "codex-2", "codex/floor", override=True
    )
    assert override_code == 0, override_output

    monkeypatch.setattr(wrkslots, "_free_bytes", lambda _path: 50 * gib)
    emergency_code, emergency_output = run_create(
        "slot03", "codex-3", "codex/emergency", override=True
    )

    assert emergency_code == 3
    assert "emergency" in emergency_output.lower()
    assert not checkout(project, "slot03").exists()


def test_clean_caches_reports_then_cleans_only_explicit_or_all_slots(
    tmp_path: Path,
) -> None:
    project, _repository, _remote = make_project(
        tmp_path,
        cache_globs=("target", "node_modules"),
    )
    assert create(project, slot="slot01", agent="codex-1", branch="codex/one").returncode == 0
    assert create(project, slot="slot02", agent="codex-2", branch="codex/two").returncode == 0
    first = checkout(project, "slot01")
    second = checkout(project, "slot02")
    for tree, payload in ((first, b"a" * 1024), (second, b"b" * 2048)):
        (tree / "target" / "debug").mkdir(parents=True)
        (tree / "target" / "debug" / "artifact").write_bytes(payload)
        (tree / "node_modules" / "package").mkdir(parents=True)
        (tree / "node_modules" / "package" / "index.js").write_text(
            "generated\n", encoding="utf-8"
        )
    source = first / "uncommitted-source.txt"
    source.write_text("must survive cache cleanup\n", encoding="utf-8")

    report = command(project, "clean-caches", "--format", "json")

    assert report.returncode == 0, report.stderr
    report_rows = {row["slot"]: row for row in json.loads(report.stdout)["slots"]}
    assert report_rows["slot01"]["action"] == "REPORT"
    assert report_rows["slot02"]["action"] == "REPORT"
    assert report_rows["slot01"]["cache_bytes"] >= 1024
    assert report_rows["slot02"]["cache_bytes"] >= 2048
    assert (first / "target").is_dir()
    assert (second / "target").is_dir()

    explicit = command(
        project,
        "clean-caches",
        "--only",
        "slot01",
        "--format",
        "json",
    )

    assert explicit.returncode == 0, explicit.stderr
    explicit_rows = {
        row["slot"]: row for row in json.loads(explicit.stdout)["slots"]
    }
    assert explicit_rows["slot01"]["action"] == "REMOVED"
    assert set(explicit_rows) == {"slot01"}
    assert not (first / "target").exists()
    assert not (first / "node_modules").exists()
    assert (second / "target").is_dir()
    assert source.read_text(encoding="utf-8") == "must survive cache cleanup\n"

    sweep = command(project, "clean-caches", "--yes", "--format", "json")

    assert sweep.returncode == 0, sweep.stderr
    sweep_rows = {row["slot"]: row for row in json.loads(sweep.stdout)["slots"]}
    assert sweep_rows["slot02"]["action"] == "REMOVED"
    assert not (second / "target").exists()
    assert not (second / "node_modules").exists()

    empty_report = command(project, "clean-caches", "--format", "json")
    assert empty_report.returncode == 0, empty_report.stderr
    empty_rows = {
        row["slot"]: row for row in json.loads(empty_report.stdout)["slots"]
    }
    assert empty_rows["slot01"]["cache_bytes"] == 0
    assert empty_rows["slot02"]["cache_bytes"] == 0


def test_agent_removal_and_clean_caches_refuse_nested_git_metadata(
    tmp_path: Path,
) -> None:
    project, repository, _remote = make_project(tmp_path, cache_globs=("target",))
    assert create(project).returncode == 0
    tree = checkout(project)
    commit_task(repository, tree, "codex/task")
    nested_git = tree / "target" / "install-build" / "dependency" / ".git"
    nested_git.mkdir(parents=True)
    sentinel = nested_git / "HEAD"
    sentinel.write_text("ref: refs/heads/main\n", encoding="utf-8")

    cleaned = command(project, "clean-caches", "--only", "slot01")

    assert cleaned.returncode == 3
    assert "nested Git metadata" in cleaned.stderr
    assert sentinel.is_file()

    handed_off = finish(project)
    assert handed_off.returncode == 0, handed_off.stderr
    mark_owner_dead(project)
    set_liveness(project, "dead")

    removed = remove(project)

    assert removed.returncode == 3
    assert "nested Git metadata" in removed.stderr
    assert sentinel.is_file()
    assert tree.is_dir()
    assert active_slots(project)


def _nested_clone(remote: Path, destination: Path) -> str:
    destination.parent.mkdir(parents=True, exist_ok=True)
    subprocess.run(
        ["git", "clone", str(remote), str(destination)],
        check=True,
        capture_output=True,
        text=True,
    )
    git(destination, "config", "user.name", "Wrkslots Test")
    git(destination, "config", "user.email", "wrkslots@example.invalid")
    git(destination, "config", "gc.autoDetach", "false")
    git(destination, "config", "maintenance.autoDetach", "false")
    # Containment must see packed remote-tracking refs, not only loose ones.
    git(destination, "pack-refs", "--all")
    assert not (destination / ".git" / "refs" / "remotes" / "origin" / "main").exists()
    return git(destination, "rev-parse", "HEAD").stdout.strip()


def _prepare_removable_agent_slot(project: Path) -> None:
    handed_off = finish(project)
    assert handed_off.returncode == 0, handed_off.stderr
    mark_owner_dead(project)
    set_liveness(project, "dead")


def _bare_upstream(tmp_path: Path, name: str, files: Mapping[str, str]) -> Path:
    """A bare repository outside every slot whose main branch commits ``files``."""

    bare = tmp_path / f"{name}.git"
    source = tmp_path / f"{name}-source"
    subprocess.run(
        ["git", "init", "--bare", "--initial-branch=main", str(bare)],
        check=True,
        capture_output=True,
        text=True,
    )
    subprocess.run(
        ["git", "clone", str(bare), str(source)],
        check=True,
        capture_output=True,
        text=True,
    )
    git(source, "config", "user.name", "Wrkslots Test")
    git(source, "config", "user.email", "wrkslots@example.invalid")
    for relative, content in files.items():
        (source / relative).parent.mkdir(parents=True, exist_ok=True)
        (source / relative).write_text(content, encoding="utf-8")
        git(source, "add", relative)
    git(source, "commit", "-m", f"{name} upstream")
    git(source, "push", "origin", "main")
    return bare


def _slot_removed_evidence(project: Path) -> list[object]:
    config = wrkslots._load_config(str(project), "testhost")
    removal_events = [
        wrkslots._as_mapping(item["payload"], "test slot-removed payload")
        for item in wrkslots._load_events(config)
        if item["kind"] == "active-state-recorded"
        and wrkslots._as_mapping(item["payload"], "test payload")["action"]
        == "slot-removed"
    ]
    assert len(removal_events) == 1
    evidence = wrkslots._as_mapping(
        removal_events[0]["evidence"], "test slot-removed evidence"
    )
    # Every event that lists deleted repositories also says what was not judged.
    scope = evidence["nested_git_scope"]
    assert isinstance(scope, str)
    assert scope == wrkslots._NESTED_GIT_SCOPE
    assert "bare Git repository under any other name" in scope
    assert "filesystem image" in scope
    return wrkslots._as_list(
        evidence["disposable_nested_repositories"], "test nested evidence"
    )


def _finish_journal(project: Path) -> Path:
    return project / "worktrees" / "ACTIVE.testhost.journal"


def test_agent_removal_deletes_provably_disposable_nested_clone_and_records_it(
    tmp_path: Path,
) -> None:
    project, repository, _remote = make_project(
        tmp_path, cache_globs=("node_modules", "target")
    )
    assert create(project).returncode == 0
    tree = checkout(project)
    commit_task(repository, tree, "codex/task")
    # Ignored build output is not work when a committed rule ignores it.
    upstream = _bare_upstream(tmp_path, "dependency", {".gitignore": "build/\n"})
    clone = tree / "target" / "deps" / "clean"
    head = _nested_clone(upstream, clone)
    (clone / "build").mkdir()
    (clone / "build" / "out.o").write_text("object\n", encoding="utf-8")
    (tree / "node_modules").mkdir()
    (tree / "node_modules" / "sentinel").write_text("cache\n", encoding="utf-8")
    _prepare_removable_agent_slot(project)

    removed = remove(project)

    assert removed.returncode == 0, removed.stderr
    dotgit = tree / "target" / "deps" / "clean" / ".git"
    assert (
        f"removed disposable nested Git repository {dotgit} head={head} "
        "contained-by=refs/remotes/origin/main ignored-entries=1"
    ) in removed.stdout.splitlines()
    assert not tree.exists()
    assert active_slots(project) == []
    assert not _finish_journal(project).exists()
    assert _slot_removed_evidence(project) == [
        {
            "checkout": "product",
            "path": str(dotgit),
            "head": head,
            "remote_ref": "refs/remotes/origin/main",
            "ignored_entries": 1,
            "ignored_sample": ["build/"],
        }
    ]


@pytest.mark.parametrize(
    "case",
    (
        "local-only-commit",
        "modified-file",
        "untracked-file",
        "stash",
        "rebase-in-progress",
        "git-file",
        "sibling-origin",
        "malformed",
        "reflog-only-commit",
        "tag-only-commit",
        "non-head-branch",
        "dropped-stash",
        "unmapped-remote-ref",
        "remote-name-with-slash",
        "url-insteadof",
        "graft",
        "replace-ref",
        "alternates",
        "gitlink",
        "skip-worktree",
        "info-exclude",
        "self-ignored-gitignore",
        "unresolvable-remote",
        "pushurl-deleted-local",
        "pushurl-inside-removal-root",
        "short-destination-uncounted",
        "mirror-refspec-uncounted",
        "symref-laundering",
        "remote-receive-pack",
        "global-insteadof-missing",
        "legacy-remotes-file",
    ),
)
def test_agent_removal_refuses_nested_repository_not_provably_disposable(
    tmp_path: Path, case: str
) -> None:
    project, repository, remote = make_project(
        tmp_path, cache_globs=("node_modules", "target")
    )
    assert create(project).returncode == 0
    tree = checkout(project)
    commit_task(repository, tree, "codex/task")
    deps = tree / "target" / "deps"
    clone = deps / "clean"
    dotgit = clone / ".git"
    only_here = "1 commit(s) exist only in this repository"
    remove_env: dict[str, str] | None = None
    # Any one of these conditions satisfies the case; only the unreferenced
    # dropped stash has two equally first commits.
    conditions: tuple[str, ...]

    def nothing_counted(sha: str, remote_name: str, reason: str) -> tuple[str, ...]:
        # With the remote uncounted no ref counts, so every commit is "only here".
        count = git(clone, "rev-list", "--count", "--all").stdout.strip()
        return (
            f"HEAD names commit {sha}, which no counted refs/remotes/* ref contains "
            f"({count} commit(s) exist only in this repository; uncounted remote(s): "
            f"{remote_name} ({reason}))",
        )

    if case == "git-file":
        clone.mkdir(parents=True)
        dotgit.write_text("gitdir: /nonexistent/worktrees/clean\n", encoding="utf-8")
        conditions = (
            ".git is a file, not a repository directory "
            "(a linked worktree or submodule pointer)",
        )
    elif case == "malformed":
        dotgit.mkdir(parents=True)
        (dotgit / "HEAD").write_text("ref: refs/heads/main\n", encoding="utf-8")
        conditions = ("not a well-formed Git repository: fatal: not a git repository",)
    elif case == "sibling-origin":
        upstream = deps / "upstream"
        upstream.mkdir(parents=True)
        git(upstream, "init", "--initial-branch=main")
        git(upstream, "config", "user.name", "Wrkslots Test")
        git(upstream, "config", "user.email", "wrkslots@example.invalid")
        head = commit_local(upstream, "file.txt", "upstream\n", "upstream")
        _nested_clone(upstream, clone)
        conditions = (
            f"HEAD names commit {head}, which no counted refs/remotes/* ref contains "
            f"({only_here}; uncounted remote(s): origin (its URL is a local path "
            "inside this removal))",
        )
    else:
        head = _nested_clone(remote, clone)
        if case == "local-only-commit":
            local = commit_local(clone, "local.txt", "local\n", "local only")
            conditions = (
                f"HEAD names commit {local}, which no counted refs/remotes/* ref "
                f"contains ({only_here})",
            )
        elif case == "modified-file":
            (clone / "seed.txt").write_text("edited\n", encoding="utf-8")
            conditions = (
                "worktree has 1 uncommitted or untracked change(s), first: ' M seed.txt'",
            )
        elif case == "untracked-file":
            (clone / "notes.txt").write_text("draft\n", encoding="utf-8")
            conditions = (
                "worktree has 1 uncommitted or untracked change(s), first: '?? notes.txt'",
            )
        elif case == "stash":
            (clone / "seed.txt").write_text("stashed\n", encoding="utf-8")
            git(clone, "stash")
            assert git(clone, "status", "--porcelain").stdout == ""
            conditions = ("stash entries exist (refs/stash)",)
        elif case == "rebase-in-progress":
            git(clone, "-c", "sequence.editor=printf 'break\\n' >", "rebase", "-i", "HEAD")
            assert (dotgit / "rebase-merge").is_dir()
            assert git(clone, "status", "--porcelain").stdout == ""
            conditions = ("a rebase is in progress (.git/rebase-merge exists)",)
        elif case == "reflog-only-commit":
            local = commit_local(clone, "local.txt", "local\n", "local only")
            git(clone, "reset", "--hard", "origin/main")
            conditions = (
                f"a reflog entry reaches commit {local}, which no counted "
                f"refs/remotes/* ref contains ({only_here})",
            )
        elif case == "tag-only-commit":
            local = commit_local(clone, "local.txt", "local\n", "local only")
            git(clone, "tag", "keep")
            git(clone, "reset", "--hard", "origin/main")
            conditions = (
                f"refs/tags/keep names commit {local}, which no counted "
                f"refs/remotes/* ref contains ({only_here})",
            )
        elif case == "non-head-branch":
            git(clone, "checkout", "-b", "side")
            local = commit_local(clone, "local.txt", "local\n", "local only")
            git(clone, "checkout", "main")
            conditions = (
                f"refs/heads/side names commit {local}, which no counted "
                f"refs/remotes/* ref contains ({only_here})",
            )
        elif case == "dropped-stash":
            (clone / "seed.txt").write_text("stashed\n", encoding="utf-8")
            git(clone, "stash")
            stashed = git(clone, "rev-parse", "refs/stash", "refs/stash^2").stdout.split()
            git(clone, "stash", "drop")
            assert git(clone, "rev-parse", "-q", "--verify", "refs/stash", check=False).returncode == 1
            conditions = tuple(
                f"commit {sha} is named by no ref, HEAD or reflog entry (for example "
                "a dropped stash or a deleted branch) and no counted refs/remotes/* "
                "ref contains it (2 commit(s) exist only in this repository)"
                for sha in stashed
            )
        elif case == "unmapped-remote-ref":
            # A ref under refs/remotes/origin/ that origin's fetch refspec does
            # not write is not evidence that origin holds the commit.
            git(clone, "config", "remote.origin.fetch", "+refs/heads/main:refs/remotes/origin/main")
            local = git(clone, "commit-tree", "HEAD^{tree}", "-p", "HEAD", "-m", "local").stdout.strip()
            git(clone, "update-ref", "refs/remotes/origin/local", local)
            conditions = (
                f"refs/remotes/origin/local names commit {local}, which no counted "
                f"refs/remotes/* ref contains ({only_here})",
            )
        elif case == "remote-name-with-slash":
            git(clone, "remote", "add", "up/stream", str(remote))
            conditions = (
                "remote 'up/stream' has a name containing '/', so its "
                "remote-tracking refs can be mistaken for another remote's",
            )
        elif case == "url-insteadof":
            git(clone, "config", "url./elsewhere.insteadOf", str(remote))
            conditions = (
                "repository config sets url./elsewhere.insteadof, which rewrites "
                "remote URLs, so a remote's configured URL may not be where its refs "
                "came from",
            )
        elif case == "graft":
            # Honoring the graft would make the dangling commit an ancestor of
            # origin/main and so look contained.
            dangling = git(clone, "commit-tree", "HEAD^{tree}", "-m", "dangling").stdout.strip()
            (dotgit / "info" / "grafts").write_text(f"{head} {dangling}\n", encoding="utf-8")
            conditions = (
                f"commit {dangling} is named by no ref, HEAD or reflog entry (for "
                "example a dropped stash or a deleted branch) and no counted "
                f"refs/remotes/* ref contains it ({only_here})",
            )
        elif case == "replace-ref":
            dangling = git(clone, "commit-tree", "HEAD^{tree}", "-m", "dangling").stdout.strip()
            replacement = git(
                clone, "commit-tree", "HEAD^{tree}", "-p", dangling, "-m", "replacement"
            ).stdout.strip()
            git(clone, "replace", head, replacement)
            conditions = (
                f"refs/replace/{head} names commit {replacement}, which no counted "
                "refs/remotes/* ref contains (2 commit(s) exist only in this repository)",
            )
        elif case == "alternates":
            (dotgit / "objects" / "info" / "alternates").write_text(
                f"{remote / 'objects'}\n", encoding="utf-8"
            )
            conditions = (
                "repository borrows objects through .git/objects/info/alternates, so "
                "its own commits cannot be told apart from another repository's",
            )
        elif case == "gitlink":
            git(clone, "update-index", "--add", "--cacheinfo", f"160000,{head},sub")
            conditions = (
                "index records 1 submodule gitlink(s), whose checkouts this check "
                "does not judge; first: 'sub'",
            )
        elif case == "skip-worktree":
            git(clone, "update-index", "--skip-worktree", "seed.txt")
            (clone / "seed.txt").write_text("hidden edit\n", encoding="utf-8")
            assert git(clone, "status", "--porcelain").stdout == ""
            conditions = (
                "index marks 1 path(s) assume-unchanged or skip-worktree, which hides "
                "changes from status; first: 'S seed.txt'",
            )
        elif case == "info-exclude":
            (dotgit / "info" / "exclude").write_text("build/\n", encoding="utf-8")
            (clone / "build").mkdir()
            (clone / "build" / "notes.txt").write_text("draft\n", encoding="utf-8")
            conditions = (
                ".git/info/exclude ignores 'build/', a local rule no commit records, "
                "so files it hides from status may be work",
            )
        elif case == "self-ignored-gitignore":
            (clone / "hide").mkdir()
            (clone / "hide" / ".gitignore").write_text("*\n", encoding="utf-8")
            (clone / "hide" / "notes.txt").write_text("draft\n", encoding="utf-8")
            assert git(clone, "status", "--porcelain").stdout == ""
            conditions = (
                "'hide/.gitignore' is ignored by its own rules, which no commit "
                "records, so files it hides from status may be work",
            )
        elif case in {"pushurl-deleted-local", "pushurl-inside-removal-root"}:
            # git push sends commits to the push URL and then updates
            # refs/remotes/origin/main as if they had reached the URL.
            pushed = (
                tmp_path / "pushed.git"
                if case == "pushurl-deleted-local"
                else deps / "pushed.git"
            )
            subprocess.run(
                ["git", "init", "--bare", "--initial-branch=main", str(pushed)],
                check=True,
                capture_output=True,
                text=True,
            )
            git(clone, "remote", "set-url", "--push", "origin", str(pushed))
            local = commit_local(clone, "local.txt", "local\n", "local only")
            git(clone, "push", "origin", "main")
            assert git(clone, "rev-parse", "refs/remotes/origin/main").stdout.strip() == local
            if case == "pushurl-deleted-local":
                shutil.rmtree(pushed)
                reason = "its push URL is a local path that does not exist"
            else:
                reason = "its push URL is a local path inside this removal"
            conditions = nothing_counted(local, "origin", reason)
        elif case == "short-destination-uncounted":
            # Git qualifies remotes/origin/main to refs/remotes/origin/main, so
            # fetching from the since-deleted 'evil' wrote origin's ref.
            local = commit_local(clone, "local.txt", "local\n", "local only")
            evil = tmp_path / "evil"
            subprocess.run(
                ["git", "clone", str(clone), str(evil)],
                check=True,
                capture_output=True,
                text=True,
            )
            git(clone, "remote", "add", "evil", str(evil))
            git(clone, "config", "--replace-all", "remote.evil.fetch", "+refs/heads/main:remotes/origin/main")
            git(clone, "fetch", "evil")
            assert git(clone, "rev-parse", "refs/remotes/origin/main").stdout.strip() == local
            shutil.rmtree(evil)
            # origin's other remote-tracking refs still count; only the one
            # 'evil' could write does not.
            still_counted = [
                refname
                for refname in git(
                    clone, "for-each-ref", "--format=%(refname)", "refs/remotes/origin/"
                ).stdout.split()
                if refname not in {"refs/remotes/origin/main", "refs/remotes/origin/HEAD"}
            ]
            assert still_counted
            count = git(
                clone, "rev-list", "--count", "--all", "--not", *still_counted
            ).stdout.strip()
            conditions = (
                f"HEAD names commit {local}, which no counted refs/remotes/* ref "
                f"contains ({count} commit(s) exist only in this repository; "
                "uncounted remote(s): evil (its URL is a local path that does not exist))",
            )
        elif case == "mirror-refspec-uncounted":
            # refs/*:refs/* lets 'evil' write refs/remotes/origin/main too.
            local = commit_local(clone, "local.txt", "local\n", "local only")
            git(clone, "remote", "add", "evil", str(tmp_path / "gone"))
            git(clone, "config", "--replace-all", "remote.evil.fetch", "+refs/*:refs/*")
            git(clone, "update-ref", "refs/remotes/origin/main", local)
            conditions = nothing_counted(
                local, "evil", "its URL is a local path that does not exist"
            )
        elif case == "symref-laundering":
            # refs/remotes/origin/HEAD resolves to a local branch; its value
            # is not evidence that origin holds anything.
            git(clone, "checkout", "-b", "side")
            local = commit_local(clone, "local.txt", "local\n", "local only")
            git(clone, "checkout", "main")
            git(clone, "symbolic-ref", "refs/remotes/origin/HEAD", "refs/heads/side")
            conditions = tuple(
                f"{refname} names commit {local}, which no counted refs/remotes/* "
                f"ref contains ({only_here})"
                for refname in ("refs/heads/side", "refs/remotes/origin/HEAD")
            )
        elif case == "remote-receive-pack":
            git(clone, "config", "remote.origin.receivepack", "git-receive-pack")
            conditions = nothing_counted(
                head,
                "origin",
                "it sets remote.origin.receivepack, so a receive-pack program this "
                "check cannot inspect carried its transfers",
            )
        elif case == "global-insteadof-missing":
            # The invoking user's configuration sent every transfer for this
            # remote to a mirror that no longer exists.
            upstream = _bare_upstream(tmp_path, "dependency", {"dep.txt": "dep\n"})
            shutil.rmtree(clone)
            head = _nested_clone(upstream, clone)
            gone = tmp_path / "gone-mirror.git"
            user_config = tmp_path / "user.gitconfig"
            user_config.write_text(
                f'[url "{gone}"]\n\tinsteadOf = {upstream}\n', encoding="utf-8"
            )
            remove_env = {"GIT_CONFIG_GLOBAL": str(user_config)}
            conditions = nothing_counted(
                head,
                "origin",
                f"its effective URL {str(gone)!r} is a local path that does not exist",
            )
        elif case == "legacy-remotes-file":
            (dotgit / "remotes").mkdir()
            (dotgit / "remotes" / "evil").write_text(
                "URL: /gone\nPull: +refs/heads/main:refs/remotes/origin/main\n",
                encoding="utf-8",
            )
            conditions = (
                "repository has remotes defined in legacy .git/remotes files, which "
                "this check does not read: evil",
            )
        else:
            assert case == "unresolvable-remote"
            # Path.resolve raises RuntimeError on a symbolic-link loop; the
            # judgment must refuse and roll back rather than escape.
            loop = tmp_path / "loop"
            loop.symlink_to(loop)
            git(clone, "remote", "set-url", "origin", str(loop))
            count = git(clone, "rev-list", "--count", "--all").stdout.strip()
            conditions = (
                f"HEAD names commit {head}, which no counted refs/remotes/* ref "
                f"contains ({count} commit(s) exist only in this repository; "
                "uncounted remote(s): origin (its URL is a local path that cannot be "
                "resolved (RuntimeError: Symlink loop from ",
            )
    (tree / "node_modules").mkdir()
    sentinel = tree / "node_modules" / "sentinel"
    sentinel.write_text("cache\n", encoding="utf-8")
    before = sorted(str(path.relative_to(tree)) for path in tree.rglob("*"))

    # Paths outside removal keep today's refusal, byte for byte: the message
    # ends at the path, with no judgment appended.
    cleaned = command(project, "clean-caches", "--only", "slot01")
    assert cleaned.returncode == 3
    candidates = [dotgit] + ([deps / "upstream" / ".git"] if case == "sibling-origin" else [])
    assert any(
        f"cache directory contains nested Git metadata: {candidate}\n" in cleaned.stderr
        for candidate in candidates
    ), cleaned.stderr
    assert "not provably disposable" not in cleaned.stderr

    _prepare_removable_agent_slot(project)
    removed = command(
        project,
        "remove",
        "slot01",
        "--coordinator-pid",
        str(os.getpid()),
        "--expected-generation",
        "1",
        env=remove_env,
    )

    assert removed.returncode == 3, removed.stdout + removed.stderr
    assert any(
        f"cache directory contains nested Git metadata: {dotgit}: "
        f"not provably disposable: {condition}" in removed.stderr
        for condition in conditions
    ), removed.stderr
    assert "removed disposable nested Git repository" not in removed.stdout
    assert "before this refusal the removal deleted" not in removed.stderr
    # Nothing was deleted: not the refused repository, not a cache the loop
    # would have reached first, not the slot.  The path fence rolled back and
    # the finish journal is gone, so the slot is not wedged.
    assert sentinel.read_text(encoding="utf-8") == "cache\n"
    assert sorted(str(path.relative_to(tree)) for path in tree.rglob("*")) == before
    assert active_slots(project)
    assert not _finish_journal(project).exists()


