@pytest.mark.parametrize("lane", ("privileged", "same-uid"))
@pytest.mark.parametrize("scenario", ("once", "persistent", "deadline", "between-pids"))
def test_process_census_preflight_discards_attempt_with_shared_bounds(
    monkeypatch: pytest.MonkeyPatch, lane: str, scenario: str,
) -> None:
    process = wrkslots._AbsentProcessObservation(123, 17, "", "pid:123")
    calls: list[str] = []
    now = 0.0
    monkeypatch.setattr(time, "monotonic", lambda: now)
    budget = wrkslots._ReadOnlyCommandBudget.start(
        timeout_seconds=5, stdout_limit=1024, stderr_limit=1024,
    )

    def snapshot() -> tuple[wrkslots._AbsentProcessObservation, ...]:
        calls.append("snapshot")
        if scenario == "between-pids":
            return (process, wrkslots._AbsentProcessObservation(124, 18, "", "pid:124"))
        return (process,) if scenario != "once" or calls.count("snapshot") == 1 else ()

    def active(observed: wrkslots._AbsentProcessObservation) -> bool:
        nonlocal now
        assert observed == process
        calls.append("identity")
        if scenario in {"deadline", "between-pids"}:
            now = 6.0
        return scenario == "between-pids"

    def observer(name: str) -> Callable[
        [Sequence[wrkslots._AbsentProcessObservation], object, wrkslots._ReadOnlyCommandBudget],
        tuple[()],
    ]:
        def observe(processes: Sequence[wrkslots._AbsentProcessObservation], _targets: object, actual: wrkslots._ReadOnlyCommandBudget) -> tuple[()]:
            assert processes == ()
            assert actual is budget
            calls.append(name)
            return ()
        return observe

    monkeypatch.setattr(wrkslots, "_absent_validate_process_snapshot", snapshot)
    monkeypatch.setattr(wrkslots, "_same_uid_process_observations", lambda _budget: snapshot())
    monkeypatch.setattr(
        wrkslots, "_read_process_stat",
        lambda path: wrkslots._ProcessStat(17 if path.name == "123" else 18, 0),
    )
    monkeypatch.setattr(
        wrkslots, "_process_is_zombie", lambda _path, **_kwargs: False
    )
    monkeypatch.setattr(wrkslots, "_process_observation_is_active", active)
    monkeypatch.setattr(wrkslots, "_absent_validate_find_matches", observer("find"))
    monkeypatch.setattr(wrkslots, "_absent_validate_maps_matches", observer("maps"))
    monkeypatch.setattr(wrkslots, "_absent_validate_mount_matches", observer("mount"))
    monkeypatch.setattr(wrkslots, "_same_uid_batched_path_matches", lambda processes, _targets, _budget: ((), ()) if processes == () else pytest.fail("stale identity reached direct path observers"))

    def capture() -> wrkslots._ProcessPathCensus:
        if lane == "privileged":
            return wrkslots._capture_process_path_census((Path("/fixture/slot"),), budget=budget)
        return wrkslots._capture_same_uid_process_path_census((Path("/fixture/slot"),), budget=budget)

    if scenario == "once":
        census = capture()
        assert census.processes == ()
        assert census.matches == ()
        assert calls == ["snapshot", "identity", "snapshot", "find", "maps", "mount"]
    else:
        with pytest.raises(wrkslots.Refusal, match="three liveness attempts" if scenario == "persistent" else "operation-wide time bound"):
            capture()
        assert calls == ["snapshot", "identity"] * (3 if scenario == "persistent" else 1)


@pytest.mark.parametrize("lane", ("privileged", "same-uid"))
@pytest.mark.parametrize(
    "evidence",
    (
        "clear",
        "live-link",
        "live-mount",
        "stale-link",
        "stale-map",
        "stale-mount",
        "mixed",
    ),
)
def test_process_census_preflight_keeps_vanished_identity_in_every_observer(
    monkeypatch: pytest.MonkeyPatch, lane: str, evidence: str,
) -> None:
    target = Path("/fixture/vanished-slot")
    processes = (
        wrkslots._AbsentProcessObservation(123, 17, "", "pid:123"),
        wrkslots._AbsentProcessObservation(124, 18, "", "pid:124"),
    )
    calls: list[str] = []
    reused = False

    def read_stat(path: Path) -> wrkslots._ProcessStat | None:
        if path.name == "123":
            return wrkslots._ProcessStat(19, 0) if reused else None
        assert path.name == "124"
        return wrkslots._ProcessStat(18, 0)

    def snapshot() -> tuple[wrkslots._AbsentProcessObservation, ...]:
        calls.append("snapshot")
        return processes

    def run(command: Sequence[str], **_kwargs: object) -> tuple[int, bytes, bytes]:
        nonlocal reused
        if "/usr/bin/find" in command:
            calls.append("find")
            assert "/proc/123/root" in command and "/proc/124/root" in command
            if evidence == "stale-link":
                reused = True
                return (0, os.fsencode(f"/proc/123/cwd\0{target}\0"), b"")
            output = os.fsencode(f"/proc/124/cwd\0{target}\0") if evidence == "live-link" else b""
            diagnostic = b"/usr/bin/find: '/proc/123/fd': No such file or directory\n"
            if evidence == "mixed":
                diagnostic += b"/usr/bin/find: '/proc/124/root': Permission denied\n"
            return (1, output, diagnostic)
        assert "/usr/bin/grep" in command
        calls.append("maps")
        assert "/proc/123/maps" in command and "/proc/124/maps" in command
        if evidence == "stale-map":
            reused = True
            return (0, os.fsencode(f"/proc/123/maps:1000-2000 r--p 00000000 00:00 1 {target}\n"), b"")
        return (2, b"", b"/usr/bin/grep: /proc/123/maps: No such file or directory\n")

    def mountinfo(
        pid: int, _budget: wrkslots._ReadOnlyCommandBudget,
        _cache: dict[str, tuple[tuple[Path, str], ...]] | None = None,
    ) -> tuple[tuple[Path, str], ...]:
        calls.append(f"mount:{pid}")
        if pid == 123:
            if evidence == "stale-mount":
                reused = True
                return ((target, str(target)),)
            try:
                raise FileNotFoundError(errno.ENOENT, "fixture generation is gone")
            except FileNotFoundError as exc:
                raise wrkslots.Refusal("mount evidence disappeared") from exc
        assert pid == 124
        return ((target, str(target)),) if evidence == "live-mount" else ()

    monkeypatch.setattr(wrkslots, "_read_process_stat", read_stat)
    monkeypatch.setattr(wrkslots, "_process_is_zombie", lambda _path: False)
    monkeypatch.setattr(wrkslots, "_absent_validate_process_snapshot", snapshot)
    monkeypatch.setattr(wrkslots, "_same_uid_process_observations", lambda _budget: snapshot())
    monkeypatch.setattr(wrkslots, "_same_uid_direct_path_processes", lambda observed, _budget: ((), observed))
    monkeypatch.setattr(wrkslots, "_root_owned_executable", lambda path, _label: wrkslots._TrustedExecutablePath(path, ()))
    monkeypatch.setattr(wrkslots, "_run_bounded_read_only_command", run)
    monkeypatch.setattr(wrkslots, "_mountinfo_path_references", mountinfo)
    budget = wrkslots._ReadOnlyCommandBudget.start(
        timeout_seconds=5, stdout_limit=4096, stderr_limit=4096,
    )

    def capture() -> wrkslots._ProcessPathCensus:
        if lane == "privileged":
            return wrkslots._capture_process_path_census((target,), budget=budget)
        return wrkslots._capture_same_uid_process_path_census((target,), budget=budget)

    if evidence.startswith("stale"):
        with pytest.raises(
            wrkslots.Refusal,
            match="identity changed after .* matched a selected path",
        ) as refused:
            capture()
        assert not isinstance(refused.value, wrkslots._ProcessEvidenceChanged)
        expected = ["snapshot", "find"]
        if evidence in {"stale-map", "stale-mount"}:
            expected.append("maps")
        if evidence == "stale-mount":
            expected.append("mount:123")
        assert calls == expected
    elif evidence == "mixed":
        with pytest.raises(wrkslots.Refusal, match="Permission denied") as refused:
            capture()
        assert not isinstance(refused.value, wrkslots._ProcessEvidenceChanged)
        assert calls == ["snapshot", "find"]
    else:
        census = capture()
        assert census.processes == processes
        assert calls == ["snapshot", "find", "maps", "mount:123", "mount:124"]
        if evidence.startswith("live"):
            with pytest.raises(wrkslots.Refusal, match="live process 124"):
                census.assert_slot_unused(target, None, ignore_current_process=False)
        else:
            assert census.matches == ()
            census.assert_slot_unused(target, None, ignore_current_process=False)


@pytest.mark.parametrize("lane", ("privileged", "same-uid"))
@pytest.mark.parametrize("result", ("clear", "in-use", "untrusted"))
def test_process_census_live_protected_identity_reaches_trusted_readers(
    monkeypatch: pytest.MonkeyPatch, lane: str, result: str,
) -> None:
    pid = os.getpid()
    generation = wrkslots._read_process_stat(Path("/proc") / str(pid))
    assert generation is not None
    process = wrkslots._AbsentProcessObservation(pid, generation.start_ticks, "", f"pid:{pid}")
    target = Path("/fixture/protected-slot")
    calls: list[str] = []
    monkeypatch.setattr(wrkslots, "_absent_validate_process_snapshot", lambda: (process,))
    monkeypatch.setattr(wrkslots, "_same_uid_process_observations", lambda _budget: (process,))
    monkeypatch.setattr(
        wrkslots, "_same_uid_direct_path_processes",
        lambda processes, _budget: ((), processes),
    )

    def trusted(path: Path, _label: str) -> wrkslots._TrustedExecutablePath:
        calls.append(path.name)
        if result == "untrusted":
            raise wrkslots.Refusal("fixture executable authority is unknown")
        return wrkslots._TrustedExecutablePath(path, ())

    def run(command: Sequence[str], **kwargs: object) -> tuple[int, bytes, bytes]:
        authorities = kwargs["trusted_executables"]
        assert isinstance(authorities, tuple)
        assert tuple(item.path for item in authorities) == (Path("/usr/bin/sudo"), Path(command[5]))
        assert command[:5] == ["/usr/bin/sudo", "-n", "-u", "root", "--"]
        if command[5] == "/usr/bin/grep":
            assert f"/proc/{pid}/maps" in command
            return (1, b"", b"")
        assert command[5] == "/usr/bin/find"
        assert f"/proc/{pid}/root" in command
        output = os.fsencode(f"/proc/{pid}/cwd\0{target}\0") if result == "in-use" else b""
        return (0, output, b"")

    def mounts(
        processes: Sequence[wrkslots._AbsentProcessObservation], _targets: object,
        _budget: wrkslots._ReadOnlyCommandBudget,
    ) -> tuple[()]:
        assert processes == (process,)
        calls.append("mount")
        return ()

    monkeypatch.setattr(wrkslots, "_root_owned_executable", trusted)
    monkeypatch.setattr(wrkslots, "_run_bounded_read_only_command", run)
    monkeypatch.setattr(wrkslots, "_absent_validate_mount_matches", mounts)
    budget = wrkslots._ReadOnlyCommandBudget.start(
        timeout_seconds=5, stdout_limit=4096, stderr_limit=1024,
    )

    def capture() -> wrkslots._ProcessPathCensus:
        if lane == "privileged":
            return wrkslots._capture_process_path_census((target,), budget=budget)
        return wrkslots._capture_same_uid_process_path_census((target,), budget=budget)

    if result == "untrusted":
        with pytest.raises(wrkslots.Refusal, match="executable authority is unknown"):
            capture()
        assert calls == ["sudo"]
        return
    census = capture()
    assert census.processes == (process,)
    assert calls == ["sudo", "find", "sudo", "grep", "mount"]
    if result == "in-use":
        with pytest.raises(wrkslots.Refusal, match=f"live process {pid}"):
            census.assert_slot_unused(target, None, ignore_current_process=False)
    else:
        census.assert_slot_unused(target, None, ignore_current_process=False)


def test_process_census_retries_when_mountinfo_owner_becomes_a_zombie(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    read_fd, release_fd = os.pipe()
    pid = os.fork()
    if pid == 0:
        os.close(release_fd)
        try:
            os.read(read_fd, 1)
        finally:
            os._exit(0)
    os.close(read_fd)
    try:
        generation = wrkslots._read_process_stat(Path("/proc") / str(pid))
        assert generation is not None
        process = wrkslots._AbsentProcessObservation(
            pid,
            generation.start_ticks,
            "/fixture",
            "mnt:[fixture]",
        )
        os.close(release_fd)
        release_fd = -1
        os.waitid(os.P_PID, pid, os.WEXITED | os.WNOWAIT)
        assert wrkslots._process_is_zombie(Path("/proc") / str(pid))

        snapshots = iter(((process,), ()))
        monkeypatch.setattr(
            wrkslots, "_absent_validate_process_snapshot", lambda: next(snapshots)
        )
        monkeypatch.setattr(
            wrkslots, "_absent_validate_find_matches", lambda *_args: ()
        )
        monkeypatch.setattr(
            wrkslots, "_absent_validate_maps_matches", lambda *_args: ()
        )

        census = wrkslots._capture_process_path_census(
            (Path("/fixture/slot-a"), Path("/fixture/slot-b"))
        )

        assert census.processes == ()
        assert census.matches == ()
    finally:
        if release_fd >= 0:
            os.close(release_fd)
        with contextlib.suppress(ProcessLookupError):
            os.kill(pid, signal.SIGKILL)
        with contextlib.suppress(ChildProcessError):
            os.waitpid(pid, 0)


def test_mountinfo_census_refuses_genuinely_unreadable_live_process(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    read_fd, release_fd = os.pipe()
    pid = os.fork()
    if pid == 0:
        os.close(release_fd)
        try:
            os.read(read_fd, 1)
        finally:
            os._exit(0)
    os.close(read_fd)
    try:
        generation = wrkslots._read_process_stat(Path("/proc") / str(pid))
        assert generation is not None
        process = wrkslots._AbsentProcessObservation(
            pid,
            generation.start_ticks,
            "/fixture",
            "mnt:[fixture]",
        )

        def unreadable(
            _pid: int,
            _budget: wrkslots._ReadOnlyCommandBudget,
            _cache: dict[str, tuple[tuple[Path, str], ...]] | None = None,
        ) -> tuple[tuple[Path, str], ...]:
            try:
                raise PermissionError(errno.EACCES, "fixture denies mount evidence")
            except PermissionError as cause:
                raise wrkslots.Refusal("mount evidence is genuinely unreadable") from cause

        monkeypatch.setattr(wrkslots, "_mountinfo_path_references", unreadable)
        budget = wrkslots._ReadOnlyCommandBudget.start(
            timeout_seconds=30,
            stdout_limit=1024,
            stderr_limit=1024,
        )
        with pytest.raises(
            wrkslots.Refusal, match="mount evidence is genuinely unreadable"
        ):
            wrkslots._mountinfo_path_references_with_retry(process, budget)
    finally:
        os.close(release_fd)
        with contextlib.suppress(ChildProcessError):
            os.waitpid(pid, 0)


@pytest.mark.parametrize("persistent", (False, True))
def test_mountinfo_census_retries_only_transient_stable_einval(
    monkeypatch: pytest.MonkeyPatch,
    persistent: bool,
) -> None:
    target = Path("/absent/validate/gone")
    process = wrkslots._AbsentProcessObservation(123, 17, "/other", "mnt:[123]")
    calls = 0

    def mountinfo(
        _pid: int,
        _budget: wrkslots._ReadOnlyCommandBudget,
        _cache: dict[str, tuple[tuple[Path, str], ...]] | None = None,
    ) -> tuple[tuple[Path, str], ...]:
        nonlocal calls
        calls += 1
        if persistent or calls == 1:
            try:
                raise OSError(errno.EINVAL, "transient procfs state")
            except OSError as cause:
                raise wrkslots.Refusal("cannot read mountinfo") from cause
        return ((target, str(target)),)

    monkeypatch.setattr(wrkslots, "_mountinfo_path_references", mountinfo)
    monkeypatch.setattr(wrkslots, "_process_start_ticks", lambda _path: 17)
    monkeypatch.setattr(
        wrkslots, "_process_observation_is_active", lambda _process: True
    )
    if persistent:
        with pytest.raises(wrkslots.Refusal, match="cannot read mountinfo"):
            wrkslots._absent_validate_mount_matches((process,), {target: "gone"})
    else:
        assert wrkslots._absent_validate_mount_matches(
            (process,), {target: "gone"}
        ) == ((123, "gone", "mount", str(target)),)
    assert calls == 2


def test_mountinfo_census_enforces_file_aggregate_and_deadline_bounds(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    observed_limits: list[int] = []
    tables = {1: b"abc", 2: b"abc", 3: b"defg"}

    def bounded_read(path: Path, _label: str, limit: int) -> bytes:
        observed_limits.append(limit)
        return tables[int(path.parent.name)]

    monkeypatch.setattr(wrkslots, "_read_bounded_regular_file", bounded_read)
    monkeypatch.setattr(
        wrkslots, "_parse_mountinfo_paths", lambda _text, _label, _cache=None: ()
    )
    budget = wrkslots._ReadOnlyCommandBudget.start(
        timeout_seconds=30,
        stdout_limit=1,
        stderr_limit=1,
        input_limit=5,
    )
    census = wrkslots._MountinfoCensus(limit=5)
    assert wrkslots._mountinfo_path_references(1, budget, census) == ()
    # An identical table is read again but charged once.
    assert wrkslots._mountinfo_path_references(2, budget, census) == ()
    assert (census.reads, census.read_bytes, census.charged_bytes) == (2, 6, 3)
    # Distinct content still has an aggregate bound, and the refusal states
    # the bound, what was already charged, and the file that crossed it.
    with pytest.raises(wrkslots.Refusal) as refused:
        wrkslots._mountinfo_path_references(3, budget, census)
    assert str(refused.value) == (
        "mountinfo census exceeded its 5-byte bound on distinct mount-table "
        "content: /proc/3/mountinfo adds 4 new bytes to the 3 bytes already "
        "charged for 1 distinct table(s) over 2 earlier read(s) of 6 bytes in "
        "this census; identical tables are charged once"
    )
    assert isinstance(refused.value, wrkslots._MountinfoCensusExceeded)
    assert census.charged_bytes == 3
    # Exceeding the bound is final for the census: even a table charged before
    # is refused afterwards, so nothing read after an unparsed table can be
    # taken as complete evidence.
    with pytest.raises(wrkslots._MountinfoCensusExceeded) as repeated:
        wrkslots._mountinfo_path_references(1, budget, census)
    assert str(repeated.value) == str(refused.value)
    # Every file is read against the fixed per-file bound, never against what
    # remains of the aggregate, so a per-file refusal names the per-file bound.
    assert observed_limits == [wrkslots._MOUNTINFO_FILE_BYTES_LIMIT] * 4
    # The census account is not the operation's command-input budget.
    assert budget.input_remaining == 5

    expired = wrkslots._ReadOnlyCommandBudget.start(
        timeout_seconds=30,
        stdout_limit=1,
        stderr_limit=1,
        input_limit=wrkslots._MOUNTINFO_CENSUS_BYTES_LIMIT,
    )
    expired.deadline = time.monotonic() - 1
    with pytest.raises(wrkslots.Refusal, match="time bound"):
        wrkslots._mountinfo_path_references(3, expired)


def test_mountinfo_census_accepts_observed_fleet_scale_above_one_twenty_eight_mib(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    one_mib = b"x" * (1024 * 1024 - 8)
    monkeypatch.setattr(
        wrkslots,
        "_read_bounded_regular_file",
        lambda path, *_args: one_mib + int(path.parent.name).to_bytes(8, "big"),
    )
    monkeypatch.setattr(
        wrkslots, "_parse_mountinfo_paths", lambda _text, _label, _cache=None: ()
    )
    budget = wrkslots._ReadOnlyCommandBudget.start(
        timeout_seconds=30,
        stdout_limit=1,
        stderr_limit=1,
        input_limit=wrkslots._MOUNTINFO_CENSUS_BYTES_LIMIT,
    )

    # A real fleet census reached 177,236,979 bytes. Exercise 192 MiB of
    # DISTINCT tables so the regression covers that observation with headroom
    # even if every table differed; the old 128 MiB aggregate ceiling would
    # refuse this sequence.
    census = wrkslots._MountinfoCensus()
    for pid in range(192):
        assert wrkslots._mountinfo_path_references(pid + 1, budget, census) == ()
    assert census.charged_bytes == 192 * 1024 * 1024
    assert census.distinct_tables == 192
    assert budget.input_remaining == wrkslots._MOUNTINFO_CENSUS_BYTES_LIMIT


def _shared_mount_table(lines: int) -> bytes:
    return "".join(
        f"{index + 40} 35 8:1 /export/{index:05d} /mnt/shared/{index:05d} "
        f"rw,relatime shared:{index} - ext4 /dev/sda1 rw\n"
        for index in range(lines)
    ).encode()


def test_unreadable_namespace_census_charges_one_shared_table_once_and_reads_every_process(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    """2,000 `pid:N` groups listing one table must not exhaust the bound.

    When a process's /proc/PID/ns/mnt link is unreadable it becomes a group of
    its own, `pid:N`, so its table is read even if it is the same table as the
    next process's.  Each read used to be charged in full, so about 1,700
    unreadable links on one ordinary table exhausted the 256 MiB bound and the
    census refused for a reason that depended only on how many links happened to
    be unreadable.  Reading every one of them is what keeps an unreadable
    namespace conservative, and that still happens; only the CHARGE is per
    distinct table.
    """

    shared = _shared_mount_table(1600)
    target = Path("/absent/validate/gone")
    holder_pid = 1234
    holder = shared + (
        f"9999 35 8:1 /export/gone {target}/root rw,relatime - ext4 /dev/sda1 rw\n"
    ).encode()
    processes = tuple(
        wrkslots._AbsentProcessObservation(pid, 17, "/other", f"pid:{pid}")
        for pid in range(1000, 3000)
    )
    assert len(shared) * len(processes) > wrkslots._MOUNTINFO_CENSUS_BYTES_LIMIT
    reads: list[int] = []

    def bounded_read(path: Path, _label: str, limit: int) -> bytes:
        assert limit == wrkslots._MOUNTINFO_FILE_BYTES_LIMIT
        pid = int(path.parent.name)
        reads.append(pid)
        return holder if pid == holder_pid else shared

    monkeypatch.setattr(wrkslots, "_read_bounded_regular_file", bounded_read)
    monkeypatch.setattr(wrkslots, "_process_start_ticks", lambda _path: 17)
    monkeypatch.setattr(wrkslots, "_process_observation_is_active", lambda _process: True)
    budget = wrkslots._ReadOnlyCommandBudget.start(
        timeout_seconds=120,
        stdout_limit=1,
        stderr_limit=1,
        input_limit=wrkslots._MOUNTINFO_CENSUS_BYTES_LIMIT,
    )

    matches = wrkslots._absent_validate_mount_matches(processes, {target: "gone"}, budget)

    assert sorted(reads) == [process.pid for process in processes]
    assert matches == ((holder_pid, "gone", "mount", f"{target}/root"),)
    assert budget.input_remaining == wrkslots._MOUNTINFO_CENSUS_BYTES_LIMIT


def test_mountinfo_census_bound_is_per_census_and_independent_of_read_order(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    """The verdict depends on the set of distinct tables in ONE census only.

    Mountinfo bytes used to be charged to the operation's command-input budget,
    which every row of a batch and every census attempt shared, so the same
    table set could pass for an early row and refuse for a later one.
    """

    monkeypatch.setattr(wrkslots, "_MOUNTINFO_CENSUS_BYTES_LIMIT", 100)
    tables = {1: b"a" * 60, 2: b"b" * 60, 3: b"a" * 60}
    monkeypatch.setattr(
        wrkslots,
        "_read_bounded_regular_file",
        lambda path, _label, _limit: tables[int(path.parent.name)],
    )
    monkeypatch.setattr(
        wrkslots, "_parse_mountinfo_paths", lambda _text, _label, _cache=None: ()
    )
    monkeypatch.setattr(wrkslots, "_process_start_ticks", lambda _path: 17)
    monkeypatch.setattr(wrkslots, "_process_observation_is_active", lambda _process: True)
    target = {Path("/absent/validate/gone"): "gone"}

    def observation(pid: int) -> wrkslots._AbsentProcessObservation:
        return wrkslots._AbsentProcessObservation(pid, 17, "/other", f"pid:{pid}")

    budget = wrkslots._ReadOnlyCommandBudget.start(
        timeout_seconds=30, stdout_limit=1, stderr_limit=1, input_limit=7
    )
    # Two censuses under one operation budget: each starts a fresh account.
    for _attempt in range(3):
        assert wrkslots._absent_validate_mount_matches((observation(1),), target, budget) == ()
        assert wrkslots._absent_validate_mount_matches((observation(2),), target, budget) == ()
    # Repeated identical content within one census is charged once.
    assert (
        wrkslots._absent_validate_mount_matches(
            (observation(1), observation(3), observation(1)), target, budget
        )
        == ()
    )
    # Distinct content over the bound still refuses, whichever comes first,
    # and the refusal names the file that crossed the bound.
    for first, second in ((1, 2), (2, 1)):
        with pytest.raises(wrkslots.Refusal) as refused:
            wrkslots._absent_validate_mount_matches(
                (observation(first), observation(second)), target, budget
            )
        assert str(refused.value) == (
            "mountinfo census exceeded its 100-byte bound on distinct mount-table "
            f"content: /proc/{second}/mountinfo adds 60 new bytes to the 60 bytes "
            "already charged for 1 distinct table(s) over 1 earlier read(s) of 60 "
            "bytes in this census; identical tables are charged once"
        )
    assert budget.input_remaining == 7


@pytest.mark.parametrize("representative", ("exited", "running"))
def test_mount_census_skips_a_lone_representative_that_exits_during_its_read(
    monkeypatch: pytest.MonkeyPatch, representative: str
) -> None:
    """An exit during the census is terminal evidence, not changed evidence.

    Process 2 is the only representative of mount namespace N2, and its
    mountinfo read fails.  If it exited during the census it is a zombie: its
    /proc directory and start ticks stay until it is reaped, but it holds no
    mount reference, so N2 is skipped and process 1's use of the selected path
    is still reported.  The census used to take matching start ticks for a
    live process and re-raise "exited during mountinfo census", so one such
    exit in each attempt refused every liveness census on a busy host.  If
    process 2 still runs, its unreadable table refuses as before.
    """

    target = Path("/absent/validate/gone")
    holder = (
        f"41 35 8:1 /export/gone {target}/root rw,relatime - ext4 /dev/sda1 rw\n"
    ).encode()
    processes = (
        wrkslots._AbsentProcessObservation(1, 17, "/other", "mnt:[N1]"),
        wrkslots._AbsentProcessObservation(2, 17, "/other", "mnt:[N2]"),
    )

    def bounded_read(path: Path, _label: str, _limit: int) -> bytes:
        if int(path.parent.name) == 2:
            raise OSError(errno.EINVAL, os.strerror(errno.EINVAL))
        return holder

    monkeypatch.setattr(wrkslots, "_read_bounded_regular_file", bounded_read)
    monkeypatch.setattr(wrkslots, "_process_start_ticks", lambda _path: 17)
    monkeypatch.setattr(
        wrkslots,
        "_process_observation_is_active",
        lambda process: process.pid != 2 or representative == "running",
    )
    budget = wrkslots._ReadOnlyCommandBudget.start(
        timeout_seconds=30, stdout_limit=1, stderr_limit=1, input_limit=1
    )

    if representative == "exited":
        assert wrkslots._absent_validate_mount_matches(
            processes, {target: "gone"}, budget
        ) == ((1, "gone", "mount", f"{target}/root"),)
    else:
        with pytest.raises(wrkslots.Refusal) as refused:
            wrkslots._absent_validate_mount_matches(processes, {target: "gone"}, budget)
        assert not isinstance(refused.value, wrkslots._ProcessEvidenceChanged)
        assert str(refused.value).startswith("mount evidence is indeterminate for PID 2:")


@pytest.mark.ordinary_environment
def test_process_path_census_reports_a_live_user_while_unrelated_processes_exit_during_it(
    tmp_path: Path, monkeypatch: pytest.MonkeyPatch
) -> None:
    """Unrelated processes exiting during the census must not hide a live user.

    On a busy host processes exit all the time, and nearly every one has a
    mount namespace of its own.  Here, in each of the census's three attempts,
    one unrelated process, alone in a new user and mount namespace, is alive
    when the census takes and preflights its snapshot, then exits and waits
    unreaped as a zombie before its mountinfo is read (the read gets EINVAL).
    The census used to refuse all three attempts with "relevant process
    evidence changed during three liveness attempts"; the process whose
    working directory is the slot must be reported instead.
    """

    slot = tmp_path / "slot"
    slot.mkdir()
    user = subprocess.Popen(["sleep", "3600"], cwd=slot, text=True)
    libc = ctypes.CDLL(None, use_errno=True)
    clone_newns, clone_newuser = 0x00020000, 0x10000000
    children: list[tuple[int, int]] = []

    def start_unrelated_process() -> int:
        release_read, release_write = os.pipe()
        ready_read, ready_write = os.pipe()
        child = os.fork()
        if child == 0:
            try:
                os.close(release_write)
                os.close(ready_read)
                libc.unshare(clone_newuser | clone_newns)
                os.write(ready_write, b"r")
                os.read(release_read, 1)
            finally:
                os._exit(0)
        os.close(release_read)
        os.close(ready_write)
        os.read(ready_read, 1)
        os.close(ready_read)
        children.append((child, release_write))
        return child

    def is_zombie(pid: int) -> bool:
        status = Path(f"/proc/{pid}/status").read_text(encoding="utf-8")
        return any(
            line.split()[1:2] == ["Z"] for line in status.splitlines() if line.startswith("State:")
        )

    real_snapshot = wrkslots._absent_validate_process_snapshot
    real_maps_matches = wrkslots._absent_validate_maps_matches

    def snapshot(
        *, include_owner_cgroups: bool = True
    ) -> tuple[wrkslots._AbsentProcessObservation, ...]:
        unrelated = start_unrelated_process()
        return tuple(
            process
            for process in real_snapshot(include_owner_cgroups=include_owner_cgroups)
            if process.pid in (user.pid, unrelated)
        )

    def maps_then_unrelated_exit(
        processes: Sequence[wrkslots._AbsentProcessObservation],
        targets: Mapping[Path, str],
        budget: wrkslots._ReadOnlyCommandBudget,
    ) -> tuple[tuple[int, str, str, str], ...]:
        matches = real_maps_matches(processes, targets, budget)
        pid, release_write = children[-1]
        os.close(release_write)
        deadline = time.monotonic() + 10
        while not is_zombie(pid):
            assert time.monotonic() < deadline, f"PID {pid} did not exit"
            time.sleep(0.01)
        return matches

    monkeypatch.setattr(wrkslots, "_absent_validate_process_snapshot", snapshot)
    monkeypatch.setattr(wrkslots, "_absent_validate_maps_matches", maps_then_unrelated_exit)
    try:
        census = wrkslots._capture_process_path_census((slot,))
        assert any(pid == user.pid for pid, *_rest in census.matches), census.matches
    finally:
        for pid, release_write in children:
            with contextlib.suppress(OSError):
                os.close(release_write)
            os.waitpid(pid, 0)
        terminate_process(user)


@pytest.mark.parametrize("overflowing_process_active", (True, False))
def test_mountinfo_census_overflow_is_not_discarded_by_representative_fallback(
    monkeypatch: pytest.MonkeyPatch, overflowing_process_active: bool
) -> None:
    """An unparsed table must refuse the census, not yield to a sibling's table.

    Processes 2 and 3 share mount namespace N2.  Process 2's table references
    the selected path; process 3's is identical to process 1's, already charged.
    When process 2's table crosses the bound it is never parsed, and falling
    back to process 3 -- whose content costs nothing to charge again -- would
    report no use.  The refusal must survive, whether or not process 2 is
    still running when its read is refused.
    """

    target = Path("/absent/validate/gone")
    clear = b"40 35 8:1 /export/a /mnt/a rw,relatime - ext4 /dev/sda1 rw\n"
    holder = (
        f"41 35 8:1 /export/gone {target}/root rw,relatime - ext4 /dev/sda1 rw\n"
    ).encode()
    tables = {1: clear, 2: holder, 3: clear}
    processes = (
        wrkslots._AbsentProcessObservation(1, 17, "/other", "mnt:[N1]"),
        wrkslots._AbsentProcessObservation(2, 17, "/other", "mnt:[N2]"),
        wrkslots._AbsentProcessObservation(3, 17, "/other", "mnt:[N2]"),
    )
    reads: list[int] = []

    def bounded_read(path: Path, _label: str, _limit: int) -> bytes:
        pid = int(path.parent.name)
        reads.append(pid)
        return tables[pid]

    monkeypatch.setattr(wrkslots, "_read_bounded_regular_file", bounded_read)
    monkeypatch.setattr(wrkslots, "_process_start_ticks", lambda _path: 17)
    monkeypatch.setattr(
        wrkslots,
        "_process_observation_is_active",
        lambda process: process.pid != 2 or overflowing_process_active,
    )
    budget = wrkslots._ReadOnlyCommandBudget.start(
        timeout_seconds=30, stdout_limit=1, stderr_limit=1, input_limit=1
    )

    # Control: with room for both distinct tables, process 2 is selected for
    # N2 and its table reports the use, so the table the bound refuses below
    # is evidence that matters.
    monkeypatch.setattr(
        wrkslots, "_MOUNTINFO_CENSUS_BYTES_LIMIT", len(clear) + len(holder)
    )
    assert wrkslots._absent_validate_mount_matches(
        processes, {target: "gone"}, budget
    ) == ((2, "gone", "mount", f"{target}/root"),)
    assert reads == [1, 2]

    reads.clear()
    monkeypatch.setattr(
        wrkslots, "_MOUNTINFO_CENSUS_BYTES_LIMIT", len(clear) + len(holder) - 1
    )
    with pytest.raises(wrkslots._MountinfoCensusExceeded) as refused:
        wrkslots._absent_validate_mount_matches(processes, {target: "gone"}, budget)
    assert str(refused.value).startswith(
        f"mountinfo census exceeded its {len(clear) + len(holder) - 1}-byte bound "
        f"on distinct mount-table content: /proc/2/mountinfo adds {len(holder)} "
        "new bytes"
    )
    # The census stops at the refused table: process 3 is never read, so its
    # previously charged content cannot stand in for process 2's.
    assert reads == [1, 2]


