def fenced_slot_path(project: Path, slot: str) -> Path | None:
    """Return the one fenced directory of ``slot`` generation 1, if it exists."""

    fenced = sorted(checkout(project, slot).parent.parent.glob(f".{slot}.fenced.1.*"))
    assert len(fenced) <= 1
    return fenced[0] if fenced else None


def test_remove_agent_batch_checks_the_fenced_path_by_identity_before_deleting(
    tmp_path: Path, monkeypatch: pytest.MonkeyPatch,
) -> None:
    """A use that begins after the fence, through an outside hard link, blocks.

    The descriptor's /proc link names the alias outside the slot, so no
    path comparison can see it.  The check after the fence compares the
    descriptor's device and inode with every entry of the fenced tree, as
    lsof does, so the slot is refused and its fence rolled back, as by
    single-slot remove.  When that scan cannot decide, the ordinary lsof
    check of the fenced path decides instead.
    """

    project, _repository, slots = dead_agent_batch_project(tmp_path)
    alias = tmp_path / "outside-alias.txt"
    os.link(checkout(project, "slot02") / "seed.txt", alias)
    holders: list[subprocess.Popen[str]] = []
    unseen_by_path_scan: list[bool] = []
    original = wrkslots._interrupt_for_test

    def start_holder_after_fence(point: str) -> None:
        fenced = fenced_slot_path(project, "slot02")
        if point == "after-path-fence" and fenced is not None and not holders:
            holder = subprocess.Popen(
                [
                    sys.executable,
                    "-c",
                    "import sys, time; handle = open(sys.argv[1]); "
                    "print('ready', flush=True); time.sleep(60)",
                    str(alias),
                ],
                cwd=tmp_path,
                text=True,
                stdout=subprocess.PIPE,
            )
            holders.append(holder)
            assert holder.stdout is not None
            assert holder.stdout.readline().strip() == "ready"
            unseen_by_path_scan.append(
                wrkslots._agent_batch_fresh_use(fenced, None, capture_generation=False)
                is None
            )
        original(point)

    monkeypatch.setattr(wrkslots, "_interrupt_for_test", start_holder_after_fence)
    try:
        returncode, payload, stderr = in_process_agent_batch(project, slots)
    finally:
        for holder in holders:
            terminate_process(holder)

    assert len(holders) == 1
    assert unseen_by_path_scan == [True]
    assert returncode == 1, stderr
    assert batch_slots(payload, "removed") == ["slot01", "slot03"]
    assert batch_slots(payload, "refused") == ["slot02"]
    reason = str(cast(list[Mapping[str, object]], payload["refused"])[0]["reason"])
    assert f"live process {holders[0].pid} uses slot" in reason
    assert ".slot02.fenced.1." in reason
    assert payload["fenced_process_scans"] == 3
    if payload["fenced_lsof_fallbacks"] == 0:
        assert f"={alias}, which is an entry of the fenced slot by device and inode" in reason
    assert payload["recovery_required"] is False
    assert checkout(project, "slot02").is_dir()
    assert fenced_slot_path(project, "slot02") is None
    assert active_slot_names(project) == ["slot02"]
    assert registry_journals(project) == []


def test_remove_agent_batch_checks_the_fenced_path_against_other_mount_namespaces(
    tmp_path: Path, monkeypatch: pytest.MonkeyPatch,
) -> None:
    """A process working in a bind alias of the fenced slot blocks deletion.

    The alias exists only in the process's own mount namespace, so its /proc
    cwd names a path the batch's fresh path scan cannot relate to the slot.
    The scan after the fence matches the directory's device and inode, and
    so does the ordinary lsof check it falls back to when it cannot decide.
    """

    probe = subprocess.run(
        ["unshare", "--user", "--map-root-user", "--mount", "true"],
        capture_output=True,
        text=True,
        check=False,
    )
    if probe.returncode != 0:
        pytest.skip(f"unprivileged mount namespaces are unavailable: {probe.stderr.strip()}")
    project, _repository, slots = dead_agent_batch_project(tmp_path, count=2)
    alias = tmp_path / "alias-mount-point"
    alias.mkdir()
    holders: list[subprocess.Popen[str]] = []
    unseen_by_path_scan: list[bool] = []
    original = wrkslots._interrupt_for_test

    def start_holder_after_fence(point: str) -> None:
        fenced = fenced_slot_path(project, "slot01")
        if point == "after-path-fence" and fenced is not None and not holders:
            holder = subprocess.Popen(
                [
                    "unshare",
                    "--user",
                    "--map-root-user",
                    "--mount",
                    "sh",
                    "-c",
                    'mount --bind "$1" "$2" && cd "$2" && echo ready && exec sleep 60',
                    "sh",
                    str(fenced),
                    str(alias),
                ],
                cwd=tmp_path,
                text=True,
                stdout=subprocess.PIPE,
            )
            holders.append(holder)
            assert holder.stdout is not None
            assert holder.stdout.readline().strip() == "ready"
            assert os.readlink(f"/proc/{holder.pid}/cwd") == str(alias)
            unseen_by_path_scan.append(
                wrkslots._agent_batch_fresh_use(fenced, None, capture_generation=False)
                is None
            )
        original(point)

    monkeypatch.setattr(wrkslots, "_interrupt_for_test", start_holder_after_fence)
    try:
        returncode, payload, stderr = in_process_agent_batch(project, slots)
    finally:
        for holder in holders:
            terminate_process(holder)

    assert len(holders) == 1
    assert unseen_by_path_scan == [True]
    assert returncode == 1, stderr
    assert batch_slots(payload, "removed") == ["slot02"]
    assert batch_slots(payload, "refused") == ["slot01"]
    reason = str(cast(list[Mapping[str, object]], payload["refused"])[0]["reason"])
    assert f"live process {holders[0].pid} uses slot" in reason
    if payload["fenced_lsof_fallbacks"] == 0:
        assert f"cwd={alias}, which is an entry of the fenced slot by device and inode" in reason
    else:
        assert 'fd="cwd"' in reason
    checked = cast(list[str], payload["fenced_lsof_fallback_reasons"])
    assert len(checked) == payload["fenced_lsof_fallbacks"]
    assert checkout(project, "slot01").is_dir()
    assert fenced_slot_path(project, "slot01") is None
    assert active_slot_names(project) == ["slot01"]
    assert registry_journals(project) == []


def test_remove_agent_batch_stops_and_names_recover_when_an_item_leaves_its_journal(
    tmp_path: Path, monkeypatch: pytest.MonkeyPatch,
) -> None:
    """A refusal whose fence cannot be rolled back stops the batch.

    The item's finish journal stays for 'wrkslots recover'; the batch reports
    recovery_required, refuses every later item without trying it, and a
    later batch naming the slot refuses before its shared scan.
    """

    project, _repository, slots = dead_agent_batch_project(tmp_path)
    holders: list[subprocess.Popen[str]] = []
    original = wrkslots._interrupt_for_test

    def hold_fenced_slot(point: str) -> None:
        fenced = fenced_slot_path(project, "slot02")
        if point == "after-path-fence" and fenced is not None and not holders:
            holders.append(subprocess.Popen(["sleep", "60"], cwd=fenced, text=True))
        original(point)

    def failing_rollback(*_args: object, **_kwargs: object) -> None:
        raise wrkslots.Refusal("injected rollback failure")

    monkeypatch.setattr(wrkslots, "_interrupt_for_test", hold_fenced_slot)
    monkeypatch.setattr(wrkslots, "_rollback_path_fence", failing_rollback)
    try:
        returncode, payload, stderr = in_process_agent_batch(project, slots)
    finally:
        for holder in holders:
            terminate_process(holder)

    journal = project / "worktrees" / "ACTIVE.testhost.journal"
    assert returncode == 1, stderr
    assert batch_slots(payload, "removed") == ["slot01"]
    assert batch_slots(payload, "refused") == ["slot02", "slot03"]
    assert payload["recovery_required"] is True
    first, later = cast(list[Mapping[str, object]], payload["refused"])
    assert first["recovery_required"] is True
    assert "path-fence rollback failed: injected rollback failure" in str(first["reason"])
    assert str(first["reason"]).endswith(
        f"an interrupted removal is recorded in {journal}; run 'wrkslots recover' "
        "before another removal"
    )
    assert "recovery_required" not in later
    assert later["reason"] == (
        "batch stopped: an earlier item left an interrupted removal; run "
        "'wrkslots recover' and retry the remaining slots"
    )
    assert "seconds" not in later
    assert journal.exists()
    assert checkout(project, "slot03").is_dir()

    monkeypatch.setattr(wrkslots, "_interrupt_for_test", original)
    again_code, again, again_stderr = in_process_agent_batch(project, ["slot03", "slot02"])
    assert again_code == 1, again_stderr
    assert again["recovery_required"] is True
    assert again["shared_process_censuses"] == 0
    assert batch_slots(again, "refused") == ["slot03", "slot02"]
    by_slot = {
        str(row["slot"]): row for row in cast(list[Mapping[str, object]], again["refused"])
    }
    assert by_slot["slot02"]["reason"] == (
        f"an interrupted removal is recorded in {journal}; run 'wrkslots recover' "
        "before another removal"
    )
    assert "run 'wrkslots recover'" in str(by_slot["slot03"]["reason"])
    text = raw_command(
        project,
        "remove-agent-batch",
        "--coordinator-pid",
        str(os.getpid()),
        "--slot=slot02=1",
    )
    assert text.returncode == 1, text.stderr
    assert "RECOVERY REQUIRED: run 'wrkslots recover' before another removal" in (
        text.stdout
    )

    # The named remedy works: recovery settles the item, and the rest proceed.
    recovered = command(project, "recover", "--coordinator-pid", str(os.getpid()))
    assert recovered.returncode == 0, recovered.stderr + recovered.stdout
    assert not journal.exists()
    finished_code, finished, finished_stderr = in_process_agent_batch(
        project, active_slot_names(project)
    )
    assert finished_code == 0, finished_stderr
    assert active_slot_names(project) == []


def in_process_agent_batch_waiting(
    project: Path, slots: Sequence[str], wait_lock: float
) -> tuple[int, dict[str, object], str]:
    """Run remove-agent-batch in this process with the global --wait-lock."""

    arguments = agent_batch_arguments(project, slots)
    stdout = io.StringIO()
    stderr = io.StringIO()
    with contextlib.redirect_stdout(stdout), contextlib.redirect_stderr(stderr):
        returncode = wrkslots.main(
            [*arguments[:2], "--wait-lock", str(wait_lock), *arguments[2:]]
        )
    text = stdout.getvalue()
    return returncode, json.loads(text) if text.strip() else {}, stderr.getvalue()


def hold_registry_with_journal(project: Path, slot: str, seconds: float) -> threading.Thread:
    """Act as another client with a removal of ``slot`` in progress.

    The thread takes the registry mutation locks, writes this machine's
    registry journal for ``slot``, holds both for ``seconds``, then retires the
    journal and releases the locks, as one registry-lock hold of an ordinary
    removal does.  It returns once the journal exists.
    """

    config = wrkslots._load_config(str(project), "testhost")
    journal = wrkslots._journal_path(config)
    ready = threading.Event()
    failures: list[BaseException] = []

    def hold() -> None:
        try:
            with wrkslots._mutation_locks(config, 10.0):
                journal.write_text(
                    json.dumps({"kind": "remove", "slot": slot}), encoding="utf-8"
                )
                ready.set()
                time.sleep(seconds)
                journal.unlink()
        except BaseException as exc:  # reported by the assertion below
            failures.append(exc)
            ready.set()

    thread = threading.Thread(target=hold, daemon=True)
    thread.start()
    assert ready.wait(10.0)
    assert failures == []
    return thread


def test_remove_agent_batch_preflight_waits_out_a_journal_another_client_holds(
    tmp_path: Path,
) -> None:
    """A journal that exists only inside another client's lock hold is not a recovery.

    The lock-free preflight read finds the journal, and the recheck under the
    registry lock finds it retired, so every slot is removed and the batch does
    not tell the operator to run 'wrkslots recover'.
    """

    project, _repository, slots = dead_agent_batch_project(tmp_path)
    holder = hold_registry_with_journal(project, "slot01", 1.0)
    try:
        returncode, payload, stderr = in_process_agent_batch(project, slots)
    finally:
        holder.join(15.0)

    assert not holder.is_alive()
    assert returncode == 0, stderr
    assert batch_slots(payload, "removed") == slots
    assert payload["refused"] == []
    assert payload["recovery_required"] is False
    assert active_slot_names(project) == []
    assert registry_journals(project) == []


def test_remove_agent_batch_keeps_going_when_a_refused_items_journal_was_in_progress(
    tmp_path: Path, monkeypatch: pytest.MonkeyPatch,
) -> None:
    """An ordinary refusal stays one item's refusal when the journal was live.

    Right after slot02 refuses, another client holds a registry journal for
    slot02 inside its lock hold.  The recheck under the lock finds it retired,
    so slot02 alone is refused and slot03 is still removed.
    """

    project, _repository, slots = dead_agent_batch_project(tmp_path)
    original = wrkslots._cmd_remove
    holders: list[threading.Thread] = []

    def refuse_slot02_while_another_client_holds_its_journal(
        args: argparse.Namespace, **kwargs: object
    ) -> int:
        if args.slot == "slot02":
            holders.append(hold_registry_with_journal(project, "slot02", 1.0))
            raise wrkslots.Refusal("injected ordinary refusal")
        return original(args, **kwargs)  # type: ignore[arg-type]

    monkeypatch.setattr(
        wrkslots, "_cmd_remove", refuse_slot02_while_another_client_holds_its_journal
    )
    try:
        returncode, payload, stderr = in_process_agent_batch(project, slots)
    finally:
        for holder in holders:
            holder.join(15.0)

    assert len(holders) == 1 and not holders[0].is_alive()
    assert returncode == 1, stderr
    assert batch_slots(payload, "removed") == ["slot01", "slot03"]
    assert batch_slots(payload, "refused") == ["slot02"]
    refused = cast(list[Mapping[str, object]], payload["refused"])[0]
    assert refused["reason"] == "injected ordinary refusal"
    assert "recovery_required" not in refused
    assert payload["recovery_required"] is False
    assert active_slot_names(project) == ["slot02"]
    assert registry_journals(project) == []


def test_remove_agent_batch_stops_without_naming_recover_when_a_journal_cannot_be_checked(
    tmp_path: Path,
) -> None:
    """A journal whose lock stays busy past --wait-lock stops the batch unconfirmed.

    Nothing is removed, and the report neither claims an interrupted removal
    nor names 'wrkslots recover'.
    """

    project, _repository, slots = dead_agent_batch_project(tmp_path)
    holder = hold_registry_with_journal(project, "slot02", 3.0)
    try:
        returncode, payload, stderr = in_process_agent_batch_waiting(project, slots, 0.5)
    finally:
        holder.join(15.0)

    assert not holder.is_alive()
    assert returncode == 1, stderr
    assert payload["removed"] == []
    assert batch_slots(payload, "refused") == slots
    assert payload["recovery_required"] is False
    assert payload["shared_process_censuses"] == 0
    by_slot = {
        str(row["slot"]): row for row in cast(list[Mapping[str, object]], payload["refused"])
    }
    assert str(by_slot["slot02"]["reason"]).startswith(
        "a removal journal for this slot exists, and whether an interrupted removal "
        "left it could not be checked under the registry lock: configuration lock is "
        "busy for "
    )
    stopped = (
        "batch stopped: a removal journal could not be checked under the registry "
        "lock; retry the remaining slots"
    )
    assert by_slot["slot03"]["reason"] == stopped
    # slot01 passed its own check before slot02 stopped the batch.
    assert by_slot["slot01"]["reason"] == stopped
    for row in by_slot.values():
        assert "recover" not in str(row["reason"])
        assert "recovery_required" not in row
    assert active_slot_names(project) == slots
    assert registry_journals(project) == []


def test_remove_agent_batch_decides_recovery_by_the_journal_not_the_state_error(
    tmp_path: Path, monkeypatch: pytest.MonkeyPatch,
) -> None:
    """A StateError raised before any journal exists refuses only its item.

    The same StateError after the item wrote its journal stops the batch and
    names 'wrkslots recover', exactly as a Refusal that leaves the journal does.
    """

    project, _repository, slots = dead_agent_batch_project(tmp_path, count=4)
    original = wrkslots._cmd_remove
    config = wrkslots._load_config(str(project), "testhost")
    journal = wrkslots._journal_path(config)

    def state_errors(args: argparse.Namespace, **kwargs: object) -> int:
        if args.slot == "slot02":
            raise wrkslots.StateError("injected invariant check before any journal")
        if args.slot == "slot03":
            journal.write_text(
                json.dumps({"kind": "remove", "slot": "slot03"}), encoding="utf-8"
            )
            raise wrkslots.StateError("injected state error after the journal")
        return original(args, **kwargs)  # type: ignore[arg-type]

    monkeypatch.setattr(wrkslots, "_cmd_remove", state_errors)
    returncode, payload, stderr = in_process_agent_batch(project, slots)

    assert returncode == 1, stderr
    assert batch_slots(payload, "removed") == ["slot01"]
    assert batch_slots(payload, "refused") == ["slot02", "slot03", "slot04"]
    assert payload["recovery_required"] is True
    invariant, interrupted, later = cast(list[Mapping[str, object]], payload["refused"])
    assert invariant["reason"] == "injected invariant check before any journal"
    assert "recovery_required" not in invariant
    assert interrupted["reason"] == (
        "injected state error after the journal; an interrupted removal is recorded "
        f"in {journal}; run 'wrkslots recover' before another removal"
    )
    assert interrupted["recovery_required"] is True
    assert later["reason"] == (
        "batch stopped: an earlier item left an interrupted removal; run "
        "'wrkslots recover' and retry the remaining slots"
    )
    assert active_slot_names(project) == ["slot02", "slot03", "slot04"]


def test_remove_agent_batch_still_reports_its_removals_after_an_unexpected_error(
    tmp_path: Path, monkeypatch: pytest.MonkeyPatch,
) -> None:
    """An exception that is not a refusal stops the batch but keeps the report.

    The slots already removed are listed, the failing slot and every later
    slot are refused, the error is in the batch's error field and ERROR: line,
    the traceback is on stderr, and the exit status is 1.
    """

    project, _repository, slots = dead_agent_batch_project(tmp_path)
    original = wrkslots._cmd_remove

    def fail_slot02(args: argparse.Namespace, **kwargs: object) -> int:
        if args.slot == "slot02":
            raise OSError("injected disk error")
        return original(args, **kwargs)  # type: ignore[arg-type]

    monkeypatch.setattr(wrkslots, "_cmd_remove", fail_slot02)
    returncode, payload, stderr = in_process_agent_batch(project, slots)

    assert returncode == 1, stderr
    assert batch_slots(payload, "removed") == ["slot01"]
    assert batch_slots(payload, "refused") == ["slot02", "slot03"]
    assert payload["error"] == "OSError: injected disk error"
    assert payload["recovery_required"] is False
    failed, later = cast(list[Mapping[str, object]], payload["refused"])
    assert failed["reason"] == (
        "unexpected error: OSError: injected disk error; the slot is still active at "
        "generation 1 and no interrupted removal is recorded"
    )
    assert "recovery_required" not in failed
    assert isinstance(failed["seconds"], float)
    assert later["reason"] == (
        "batch stopped after an unexpected error; retry the remaining slots"
    )
    assert "wrkslots: remove-agent-batch stopped on an unexpected error:" in stderr
    assert "Traceback (most recent call last):" in stderr
    assert "OSError: injected disk error" in stderr
    assert active_slot_names(project) == ["slot02", "slot03"]
    assert registry_journals(project) == []

    human = io.StringIO()
    human_stderr = io.StringIO()
    arguments = agent_batch_arguments(project, ["slot02"])
    arguments[arguments.index("json")] = "human"
    with contextlib.redirect_stdout(human), contextlib.redirect_stderr(human_stderr):
        human_code = wrkslots.main(arguments)
    assert human_code == 1, human_stderr.getvalue()
    lines = human.getvalue().splitlines()
    assert lines[0].startswith("requested=1 removed=0 refused=1 ")
    assert lines[-1] == "ERROR: OSError: injected disk error"

    monkeypatch.setattr(wrkslots, "_cmd_remove", original)
    finished_code, finished, finished_stderr = in_process_agent_batch(
        project, ["slot02", "slot03"]
    )
    assert finished_code == 0, finished_stderr
    assert finished["error"] is None
    assert active_slot_names(project) == []


def test_remove_agent_batch_reports_an_unexpected_error_in_its_shared_scan(
    tmp_path: Path, monkeypatch: pytest.MonkeyPatch,
) -> None:
    project, _repository, slots = dead_agent_batch_project(tmp_path)

