def test_remove_agent_batch_describes_the_item_an_unexpected_error_interrupted(
    tmp_path: Path, monkeypatch: pytest.MonkeyPatch,
) -> None:
    """The failing item's reason says what the registry shows afterwards.

    A removal that completed before the error is named as possibly complete;
    one that left its journal names 'wrkslots recover'.
    """

    project, _repository, slots = dead_agent_batch_project(tmp_path)
    original = wrkslots._cmd_remove
    config = wrkslots._load_config(str(project), "testhost")
    journal = wrkslots._journal_path(config)

    def fail_after(args: argparse.Namespace, **kwargs: object) -> int:
        if args.slot == "slot02":
            original(args, **kwargs)  # type: ignore[arg-type]
            raise OSError("injected error after the removal")
        if args.slot == "slot03":
            journal.write_text(
                json.dumps({"kind": "remove", "slot": "slot03"}), encoding="utf-8"
            )
            raise OSError("injected error after the journal")
        return original(args, **kwargs)  # type: ignore[arg-type]

    monkeypatch.setattr(wrkslots, "_cmd_remove", fail_after)
    returncode, payload, stderr = in_process_agent_batch(project, ["slot01", "slot02"])

    assert returncode == 1, stderr
    assert batch_slots(payload, "removed") == ["slot01"]
    assert batch_slots(payload, "refused") == ["slot02"]
    failed = cast(list[Mapping[str, object]], payload["refused"])[0]
    assert failed["reason"] == (
        "unexpected error: OSError: injected error after the removal; the slot is no "
        "longer active at generation 1, so its removal may have completed before the "
        "error; read 'wrkslots status'"
    )
    assert active_slot_names(project) == ["slot03"]

    returncode, payload, stderr = in_process_agent_batch(project, ["slot03"])

    assert returncode == 1, stderr
    assert payload["recovery_required"] is True
    failed = cast(list[Mapping[str, object]], payload["refused"])[0]
    assert failed["reason"] == (
        "unexpected error: OSError: injected error after the journal; an interrupted "
        f"removal is recorded in {journal}; run 'wrkslots recover' before another removal"
    )
    assert failed["recovery_required"] is True


def test_remove_agent_batch_reports_each_items_disposable_nested_repositories(
    tmp_path: Path,
) -> None:
    project, repository, remote = make_project(tmp_path, cache_globs=("target",))
    slots = ["slot01", "slot02", "slot03"]
    heads: dict[str, str] = {}
    for index, slot in enumerate(slots, start=1):
        made = create(project, slot=slot, agent=f"codex-{index}", branch=f"codex/{slot}")
        assert made.returncode == 0, made.stderr
        tree = checkout(project, slot)
        commit_task(repository, tree, f"codex/{slot}")
        if slot != "slot02":
            heads[slot] = _nested_clone(remote, tree / "target" / "deps" / "clean")
        handed_off = finish(project, slot, f"codex-{index}")
        assert handed_off.returncode == 0, handed_off.stderr
    for slot in slots:
        mark_owner_dead(project, slot=slot)
    set_liveness(project, "dead")

    def evidence(slot: str) -> dict[str, object]:
        return {
            "checkout": "product",
            "path": str(checkout(project, slot) / "target" / "deps" / "clean" / ".git"),
            "head": heads[slot],
            "remote_ref": "refs/remotes/origin/main",
            "ignored_entries": 0,
            "ignored_sample": [],
        }

    returncode, payload, stderr = in_process_agent_batch(project, ["slot01", "slot02"])

    assert returncode == 0, stderr
    rows = {
        str(row["slot"]): row for row in cast(list[Mapping[str, object]], payload["removed"])
    }
    assert rows["slot01"]["disposable_nested_repositories"] == [evidence("slot01")]
    assert rows["slot02"]["disposable_nested_repositories"] == []

    text = raw_command(
        project,
        "remove-agent-batch",
        "--coordinator-pid",
        str(os.getpid()),
        "--slot=slot03=1",
    )
    assert text.returncode == 0, text.stderr
    lines = text.stdout.splitlines()
    removed_at = lines.index("REMOVED: slot03 generation=1")
    nested = evidence("slot03")
    # The same line single-slot remove prints, directly under its item.
    assert lines[removed_at + 1] == (
        f"removed disposable nested Git repository {nested['path']} "
        f"head={nested['head']} contained-by=refs/remotes/origin/main "
        "ignored-entries=0"
    )
    assert active_slot_names(project) == []


def test_remove_agent_batch_exit_status_counts_and_input_file(tmp_path: Path) -> None:
    project, _repository, slots = dead_agent_batch_project(tmp_path)

    duplicate = raw_command(
        project,
        "remove-agent-batch",
        "--coordinator-pid",
        str(os.getpid()),
        "--slot=slot01=1",
        "--slot=slot01=1",
    )
    assert duplicate.returncode == 3
    assert "same slot more than once" in duplicate.stderr
    empty = raw_command(
        project, "remove-agent-batch", "--coordinator-pid", str(os.getpid())
    )
    assert empty.returncode == 3
    assert "at least one --slot" in empty.stderr

    stale = remove_agent_batch(project, ["slot01"], env=None)
    stale_generation = raw_command(
        project,
        "remove-agent-batch",
        "--coordinator-pid",
        str(os.getpid()),
        "--slot=slot02=7",
        "--slot=missing=1",
    )
    # The first call removed slot01; the second removed nothing and must fail.
    assert stale.returncode == 0, stale.stderr
    assert stale_generation.returncode == 1, stale_generation.stderr
    assert "requested=2 removed=0 refused=2" in stale_generation.stdout
    assert "REFUSED: slot02 generation=7 reason=slot slot02 generation is 1, not 7" in (
        stale_generation.stdout
    )
    assert "REFUSED: missing generation=1" in stale_generation.stdout

    listing = tmp_path / "slots.txt"
    listing.write_text("# dead-owner rows\n\nslot02=1\n  slot03=1  \n", encoding="utf-8")
    from_file = raw_command(
        project,
        "remove-agent-batch",
        "--coordinator-pid",
        str(os.getpid()),
        "--input",
        str(listing),
    )
    assert from_file.returncode == 0, from_file.stderr + from_file.stdout
    assert "requested=2 removed=2 refused=0 shared_process_censuses=1" in from_file.stdout
    assert "REMOVED: slot02 generation=1" in from_file.stdout
    assert "REMOVED: slot03 generation=1" in from_file.stdout
    assert active_slot_names(project) == []
    assert all(not checkout(project, slot).exists() for slot in slots)
    archive = json.loads(
        (project / "worktrees" / "ARCHIVED.testhost.json").read_text(encoding="utf-8")
    )
    assert sorted(str(row["slot"]) for row in archive["records"]) == slots


def test_remove_agent_batch_refuses_validation_and_absent_rows_per_item(
    tmp_path: Path,
) -> None:
    project, _repository, slots = dead_agent_batch_project(tmp_path, count=2)
    shutil.rmtree(checkout(project, "slot02").parent)

    result = remove_agent_batch(project, slots)

    assert result.returncode == 1, result.stderr
    payload = json.loads(result.stdout)
