def test_remove_agent_batch_refuses_an_item_whose_budget_runs_out_just_before_deletion(
    tmp_path: Path, monkeypatch: pytest.MonkeyPatch,
) -> None:
    """The last budget check sits between the final use check and the first deletion.

    A budget spent after every bounded step has finished still refuses the
    item there, and the refusal rolls the fence back before anything is
    deleted.
    """

    project, _repository, slots = dead_agent_batch_project(tmp_path, count=2)
    expired: list[str] = []
    original = wrkslots._end_item_deadline

    def expire_then_end() -> None:
        deadline = wrkslots._ITEM_DEADLINE.get()
        if deadline is not None and deadline.state == "active" and not expired:
            assert fenced_slot_path(project, "slot01") is not None
            expire_item_budget()
            expired.append("slot01")
        original()

    monkeypatch.setattr(wrkslots, "_end_item_deadline", expire_then_end)
    returncode, payload, stderr = in_process_agent_batch(project, slots)

    assert expired == ["slot01"]
    assert returncode == 1, stderr
    assert batch_slots(payload, "removed") == ["slot02"]
    assert batch_slots(payload, "refused") == ["slot01"]
    reason = str(cast(list[Mapping[str, object]], payload["refused"])[0]["reason"])
    assert reason.startswith(
        "this remove-agent-batch item used its 60-second budget for work before "
        "deletion at the first deletion; nothing in the slot was deleted"
    )
    assert payload["recovery_required"] is False
    assert checkout(project, "slot01").is_dir()
    assert fenced_slot_path(project, "slot01") is None
    assert active_slot_names(project) == ["slot01"]
    assert registry_journals(project) == []


def test_item_budget_stops_git_with_sigterm_first_so_git_can_remove_its_locks(
    tmp_path: Path, monkeypatch: pytest.MonkeyPatch,
) -> None:
    fake_bin = tmp_path / "bin"
    fake_bin.mkdir()
    marker = tmp_path / "signals"
    fake_git = fake_bin / "git"
    fake_git.write_text(
        "#!/bin/sh\n"
        f"trap 'echo TERM >> {shlex.quote(str(marker))}; exit 143' TERM\n"
        "while :; do sleep 0.05; done\n",
        encoding="utf-8",
    )
    fake_git.chmod(0o755)
    monkeypatch.setenv("PATH", f"{fake_bin}{os.pathsep}{os.environ['PATH']}")
    context = wrkslots._AgentRemoveBatchContext({}, item_seconds=0.5)
    started = time.monotonic()
    with wrkslots._agent_batch_item_deadline(context):
        with pytest.raises(
            wrkslots.Refusal,
            match=re.escape(
                "this remove-agent-batch item used its 0.5-second budget for work "
                f"before deletion at git status --short in {tmp_path};"
            ),
        ):
            wrkslots._GitVcs._run(tmp_path, ["status", "--short"])
    elapsed = time.monotonic() - started

    assert marker.read_text(encoding="utf-8") == "TERM\n"
    assert elapsed < 0.5 + wrkslots._AGENT_REMOVE_BATCH_TERM_GRACE_SECONDS
    assert context.last_seconds_before_deletion is None


def process_has_exited(pid: int, seconds: float = 5.0) -> bool:
    """Return whether ``pid`` is gone or a zombie within ``seconds``."""

    deadline = time.monotonic() + seconds
    while True:
        try:
            state = Path(f"/proc/{pid}/stat").read_text(encoding="utf-8").rsplit(") ", 1)[1][:1]
        except (OSError, IndexError):
            return True
        if state in {"Z", "X"}:
            return True
        if time.monotonic() >= deadline:
            return False
        time.sleep(0.05)


def test_item_budget_kills_a_command_that_ignores_sigterm_and_its_descendants(
    tmp_path: Path, monkeypatch: pytest.MonkeyPatch,
) -> None:
    monkeypatch.setattr(wrkslots, "_AGENT_REMOVE_BATCH_TERM_GRACE_SECONDS", 0.5)
    pids = tmp_path / "pids"
    script = (
        "trap '' TERM; sleep 60 & echo $$ $! > \"$1.tmp\"; mv \"$1.tmp\" \"$1\"; "
        "while :; do sleep 0.05; done"
    )
    started = time.monotonic()
    with pytest.raises(
        wrkslots.Refusal,
        match="used its 60-second budget for work before deletion at a test command;",
    ):
        wrkslots._run_within_item_budget(
            ["sh", "-c", script, "sh", str(pids)], seconds=1.0, what="a test command"
        )
    elapsed = time.monotonic() - started

    shell_pid, sleeper_pid = (int(value) for value in pids.read_text().split())
    assert 1.0 <= elapsed < 1.0 + 0.5 + wrkslots._AGENT_REMOVE_BATCH_REAP_SECONDS
    # The command itself was reaped; its background child, which ignored
    # SIGTERM too, was killed with its process group.
    assert not Path(f"/proc/{shell_pid}").exists()
    assert process_has_exited(sleeper_pid)


def test_remove_agent_batch_stops_for_a_pending_operation_that_has_no_journal_file(
    tmp_path: Path, monkeypatch: pytest.MonkeyPatch,
) -> None:
    """A mutation records its progress before it writes its journal file.

    One interrupted between the two leaves only the pending operation in the
    append-only history.  The batch finds it, stops, and names recover.
    """

    project, _repository, slots = dead_agent_batch_project(tmp_path, count=2)
    config = wrkslots._load_config(str(project), "testhost")
    journal_path = wrkslots._journal_path(config)
    original_write = wrkslots._atomic_write_json

    def interrupted_write(path: Path, value: object) -> None:
        if path == journal_path:
            raise OSError(errno.EIO, "interrupted before the journal file was written")
        original_write(path, value)

    monkeypatch.setattr(wrkslots, "_atomic_write_json", interrupted_write)
    with pytest.raises(OSError, match="interrupted before the journal file"):
        wrkslots._write_journal(
            config,
            {"kind": "remove", "slot": "slot02", "machine": config.machine, "generation": 1},
        )
    monkeypatch.setattr(wrkslots, "_atomic_write_json", original_write)
    assert not journal_path.exists()
    assert wrkslots._removal_journal_candidate(config, "slot01") is None
    assert wrkslots._removal_journal_candidate(config, "slot02") == journal_path

    returncode, payload, stderr = in_process_agent_batch(project, slots)

    assert returncode == 1, stderr
    assert batch_slots(payload, "removed") == []
    refused = {
        str(row["slot"]): row for row in cast(list[Mapping[str, object]], payload["refused"])
    }
    assert set(refused) == set(slots)
    assert refused["slot02"]["reason"] == (
        f"an interrupted removal is recorded in {journal_path}; run 'wrkslots "
        "recover' before another removal"
    )
    assert refused["slot02"]["recovery_required"] is True
    assert str(refused["slot01"]["reason"]).startswith(
        "batch stopped: an interrupted removal must be recovered first"
    )
    assert payload["recovery_required"] is True
    assert active_slot_names(project) == slots


def test_removal_journal_candidate_counts_a_history_that_cannot_be_replayed(
    tmp_path: Path,
) -> None:
    project, _repository, _slots = dead_agent_batch_project(tmp_path, count=1)
    config = wrkslots._load_config(str(project), "testhost")
    assert wrkslots._removal_journal_candidate(config, "slot01") is None
    events = wrkslots._event_directory(config, config.machine)
    # A pending operation whose embedded journal names another machine.
    wrkslots._event_writer(config, config.machine).append(
        "operation-progress-recorded",
        {
            "slot": "slot01",
            "operation": "remove",
            "journal_path": wrkslots._journal_path(config).name,
            "journal": {"kind": "remove", "slot": "slot01", "machine": "elsewhere"},
        },
    )
    with pytest.raises(wrkslots.StateError, match="does not match its embedded journal"):
        wrkslots._pending_operations_from_events(config, config.machine)
    assert wrkslots._removal_journal_candidate(config, "slot01") == events
    assert wrkslots._removal_journal_candidate(config, "slot02") == events

    returncode, payload, stderr = in_process_agent_batch(project, ["slot01"])
    assert returncode == 1, stderr
    assert payload["refused"] == [
        {
            "slot": "slot01",
            "generation": 1,
            "reason": (
                f"the append-only history in {events} cannot be replayed, so an "
                "interrupted removal cannot be ruled out; run 'wrkslots recover' "
                "before another removal"
            ),
            "recovery_required": True,
        }
    ]
    assert payload["recovery_required"] is True
    assert active_slot_names(project) == ["slot01"]
    assert checkout(project, "slot01").is_dir()


def test_remove_agent_batch_honors_a_live_owners_release_like_remove(
    tmp_path: Path,
) -> None:
    """A release by the live owner authorizes a batch item exactly as it does remove.

    Before the release the owner is alive and its heartbeat is fresh, so the
    batch refuses the slot. After it, the batch removes the slot without
    --coordinator-authorized and records the same owner-release-honored
    evidence, and a live process in the owner's cgroup that touches nothing in
    the slot does not block.
    """

    project, repository, _remote = make_project(tmp_path)
    assert create(project).returncode == 0
    commit_task(repository, checkout(project), "codex/task")
    _write_owner_handoff(project, tmp_path)
    tree = checkout(project)

    before = remove_agent_batch(project, ["slot01"])

    assert before.returncode == 1, before.stderr
    payload = json.loads(before.stdout)
    assert batch_slots(payload, "removed") == []
    assert batch_slots(payload, "refused") == ["slot01"]
    reason = str(cast(list[Mapping[str, object]], payload["refused"])[0]["reason"])
    assert reason.startswith(
        "remove requires a proven-dead recorded owner or an owner-consented handoff; "
        "owner is live"
    )
    assert tree.is_dir()
    assert active_slot_names(project) == ["slot01"]
    assert _owner_release_honored(project) == []

    released = _release(project)
    assert released.returncode == 0, released.stderr
    _read_owner_handoff(project)
    owner = wrkslots._read_process_identity(os.getpid())
    sibling = subprocess.Popen(["sleep", "600"], cwd=tmp_path, text=True)
    try:
        assert (
            wrkslots._read_process_identity(sibling.pid).cgroup_path == owner.cgroup_path
        )
        after = remove_agent_batch(project, ["slot01"])
        assert sibling.poll() is None
    finally:
        terminate_process(sibling)

    assert after.returncode == 0, after.stderr
    payload = json.loads(after.stdout)
    assert batch_slots(payload, "removed") == ["slot01"]
    assert payload["refused"] == []
    assert payload["shared_process_censuses"] == 1
    assert not tree.exists()
    assert active_slot_names(project) == []
    honored = _owner_release_honored(project)
    assert len(honored) == 1
    evidence = wrkslots._as_mapping(
        wrkslots._as_mapping(honored[0]["payload"], "payload")["evidence"], "evidence"
    )
    assert evidence["basis"] == "owner-released"
    assert evidence["owner_state"] == "live"
    assert evidence["owner"] == wrkslots._identity_to_obj(owner)
    assert evidence["coordinator_authorized"] is False
    assert registry_journals(project) == []


